-- =============================================================================
-- 487 — LE CAHIER D'EXERCICES DE 4E (partie 6)
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/4e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 487 --niveau 4e --fichiers histoire-geo.n2,latin.n1,maths.n1 --suffixe 6 > supabase/contenu/487_exercices_4e_6.sql
--
-- 72 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (5/10/15 gemmes, 20/35/50 XP), réglables ensuite en base.
--
--   histoire-geo.n2         27 exercices · 9 chapitres
--   latin.n1                 9 exercices · 3 chapitres
--   maths.n1                36 exercices · 12 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('9d5de0b0-162d-5646-8a5c-b20837b5bed7'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La République à la loupe de la frise","competence":"se-reperer-temps","situation":"Lina prépare son contrôle sur la Troisième République. Elle place six repères sur une frise, de 1870 à 1910.","documents":[{"id":"frise","type":"frise","titre":"La Troisième République, 1870-1910","debut":1870,"fin":1910,"pas":5,"periodes":[{"id":"z1","debut":1894,"fin":1906,"nom":"Affaire Dreyfus","teinte":"corail"}],"evenements":[{"id":"z2","date":1870,"nom":"Proclamation"},{"id":"z3","date":1875,"nom":"Amend. Wallon"},{"id":"z4","date":1881,"nom":"Lois Ferry"},{"id":"z5","date":1898,"nom":"J’accuse…!"},{"id":"z6","date":1901,"nom":"Associations"},{"id":"z7","date":1905,"nom":"Séparation"}]}],"questions":[{"enonce":"Touche l’événement qui rend l’école primaire **gratuite, laïque et obligatoire**.","aide":"Cherche le nom du ministre dont les lois portent le nom.","type":"zone","document":"frise","multiple":false},{"enonce":"Range ces quatre repères du plus ancien au plus récent.","aide":"Lis la frise de gauche à droite.","type":"ordre","items":[{"id":"a","texte":"Proclamation de la République"},{"id":"b","texte":"Lois Jules Ferry"},{"id":"c","texte":"Amendement Wallon"},{"id":"d","texte":"Séparation des Églises et de l’État"}]},{"enonce":"Combien d’années séparent l’amendement Wallon de la loi de séparation des Églises et de l’État ?","aide":"Soustrais la date de l’amendement Wallon à celle de la séparation.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"Les **lois Jules Ferry** (1881-1882) rendent l’école primaire gratuite, laïque et obligatoire : elles sont placées en **1881** sur la frise."},{"cle":{"type":"ordre","ids":["a","c","b","d"]},"explication":"**1870 → 1875 → 1881 → 1905** : la République est proclamée, s’impose à une voix, se donne l’école, puis sépare l’Église et l’État."},{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30 ans","explication":"1905 − 1875 = **30 ans** : en une génération, la République a bâti l’école, les libertés et la laïcité."}]$ex$::jsonb),
  ('9d5de0b0-162d-5646-8a5c-b20837b5bed7'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"La lettre de l’instituteur de Saint-Pol","competence":"analyser-texte","situation":"En 1884, un instituteur breton écrit à son inspecteur pour décrire sa classe. Tu lis sa lettre pour comprendre ce que la République attend de l’école.","documents":[{"id":"lettre","type":"texte","genre":"lettre","titre":"Lettre d’un instituteur, octobre 1884","auteur":"Texte écrit pour l’exercice.","blocs":["Saint-Pol-de-Léon, le 12 octobre 1884. Monsieur l’Inspecteur, vous me demandez des nouvelles de ma classe. Elle compte quarante élèves de six à treize ans. Depuis les lois de 1881-1882, l’école ne coûte plus rien aux familles, et elle est obligatoire : les bancs se remplissent.","Le matin, je fais lire, écrire et compter. L’après-midi, je raconte l’histoire de la France et nous chantons la Marseillaise. Chaque semaine, une leçon de civisme explique aux enfants ce que sera leur rôle de citoyen.","À la maison, mes élèves ne parlent que le breton. En classe, je les oblige à répondre en français : c’est lent, mais c’est ainsi qu’ils pourront un jour lire la loi et voter en connaissance de cause.","Le curé me regarde d’un œil méfiant : le village se partage entre ceux qui vont à l’église et ceux qui viennent à mon école. Pourtant, les parents m’appellent « monsieur l’instituteur » et me demandent d’écrire leurs lettres.","Rose, ma plus jeune élève, a eu six ans en 1883. D’après la loi, elle doit rester à l’école jusqu’à ses treize ans."]}],"questions":[{"enonce":"Touche le mot qui désigne la langue régionale que l’école de la République cherche à faire reculer.","aide":"Relis le troisième paragraphe : que parlent les élèves à la maison ?","type":"zone","document":"lettre","multiple":false},{"enonce":"Pourquoi l’instituteur impose-t-il le français en classe ?","aide":"La lettre donne la raison à la fin du troisième paragraphe.","type":"choix","options":[{"id":"a","texte":"Parce que le curé a demandé que la messe soit dite en français"},{"id":"b","texte":"Pour que l’inspecteur puisse compter les mots appris par chaque enfant"},{"id":"c","texte":"Parce que le breton est interdit dans toutes les familles du village"},{"id":"d","texte":"Pour que tous les futurs citoyens partagent une langue commune et comprennent la loi"}],"multiple":false},{"enonce":"Associe chaque activité de la classe à ce qu’elle apporte à la République.","aide":"Pense à ce que chaque activité prépare : un savoir, une mémoire, un symbole ou un rôle.","type":"association","gauche":[{"id":"g0","texte":"Lire, écrire, compter"},{"id":"g1","texte":"L’histoire de la France"},{"id":"g2","texte":"Chanter la Marseillaise"},{"id":"g3","texte":"La leçon de civisme"}],"droite":[{"id":"d0","texte":"Les devoirs du futur citoyen"},{"id":"d1","texte":"Le sentiment d’appartenir à la nation"},{"id":"d2","texte":"Un symbole républicain partagé"},{"id":"d3","texte":"Les outils de base de chaque élève"}]},{"enonce":"Rose a eu six ans en 1883. En quelle année aura-t-elle treize ans, l’âge où finit l’obligation scolaire ?","aide":"Compte le nombre d’années entre six ans et treize ans.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m93"]},"explication":"Les élèves parlent le **breton** à la maison. L’école de la République enseigne le français à tous, contre les langues régionales."},{"cle":{"type":"choix","ids":["d"]},"explication":"Il veut que ses élèves puissent « lire la loi et voter en connaissance de cause » : le **français** unit les citoyens d’une même nation."},{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"L’école de la République forme des **citoyens** : elle donne les savoirs de base, une histoire commune, des symboles et une éducation civique."},{"cle":{"type":"nombre","valeur":1890,"tolerance":0},"affichage":"1890","explication":"De 6 à 13 ans, il y a 7 ans : 1883 + 7 = **1890**."}]$ex$::jsonb),
  ('9d5de0b0-162d-5646-8a5c-b20837b5bed7'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Un dîner de famille pendant l’affaire Dreyfus","competence":"analyser-document","situation":"Léo lit une scène de famille de 1898. Il la rapproche d’une frise pour comprendre pourquoi cette affaire a déchiré la France, et ce que la République en a gardé.","documents":[{"id":"frise","type":"frise","titre":"L’affaire Dreyfus","debut":1892,"fin":1908,"pas":2,"periodes":[{"id":"z1","debut":1894,"fin":1906,"nom":"L’affaire","teinte":"corail"}],"evenements":[{"id":"z2","date":1894,"nom":"Dreyfus condamné"},{"id":"z3","date":1898,"nom":"J’accuse…!"},{"id":"z4","date":1906,"nom":"Réhabilitation"}]},{"id":"scene","type":"texte","genre":"article","titre":"Dîner du dimanche, janvier 1898","auteur":"Scène imaginée pour l’exercice.","blocs":["Chez les Moreau, on ne parle plus que de l’affaire. Le grand-père lit le journal chaque matin et reste sûr que l’officier condamné est coupable : « L’armée ne se trompe pas », répète-t-il.","Sa petite-fille Camille, elle, vient de lire la lettre ouverte d’un écrivain célèbre, publiée cette semaine. Elle répond que le procès a été injuste.","La discussion s’échauffe. En ville, d’anciens amis ne se parlent plus, et des manifestations ont lieu dans la rue."]}],"questions":[{"enonce":"Camille a lu, en janvier 1898, une lettre ouverte d’un écrivain célèbre. Touche l’événement de la frise qui correspond.","aide":"Cherche l’événement de 1898 : le titre de la lettre est une accusation.","type":"zone","document":"frise","multiple":false},{"enonce":"Le dîner a lieu en 1898. Combien d’années s’écoulent encore avant la réhabilitation de Dreyfus ?","aide":"Lis la date de la réhabilitation sur la frise, puis soustrais 1898.","type":"nombre","unite":"ans"},{"enonce":"Touche le mot du texte qui désigne le jugement que Camille trouve injuste.","aide":"Camille ne conteste pas l’armée mais ce qui s’est passé devant les juges.","type":"zone","document":"scene","multiple":false},{"enonce":"Que montre cette scène de famille sur l’affaire Dreyfus ?","aide":"Regarde la fin du texte : qui ne se parle plus ?","type":"choix","options":[{"id":"a","texte":"Elle se règle en quelques jours, sans débat dans la société"},{"id":"b","texte":"Elle divise les Français jusque dans les familles et entre amis"},{"id":"c","texte":"Elle n’intéresse que les militaires et quelques journalistes"},{"id":"d","texte":"Elle met d’accord tous les Français contre l’armée"}],"multiple":false},{"enonce":"Complète la conclusion du chapitre.","aide":"La crise a été grave, mais le régime n’a pas disparu : il a défendu une valeur.","type":"trous","segments":["Malgré cette crise, la République ",0," et en sort plus attachée à la ",1,"."],"banque":["armée","tient","tombe","justice"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"En janvier **1898**, Émile Zola publie « J’accuse…! » pour défendre Dreyfus. C’est la lettre que Camille a lue."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 ans","explication":"1906 − 1898 = **8 ans** : l’affaire dure en tout douze ans, de 1894 à 1906."},{"cle":{"type":"zone","ids":["m55"]},"explication":"Camille trouve le **procès** injuste : Dreyfus a été condamné à tort, et c’est le cœur de l’affaire."},{"cle":{"type":"choix","ids":["b"]},"explication":"Grand-père et petite-fille s’opposent, des amis se brouillent : l’affaire **divise la société française** en profondeur."},{"cle":{"type":"trous","trous":[["tient","resiste","survit"],["justice"]]},"affichage":"tient · justice","explication":"La République **tient** et sort renforcée dans son attachement à la **justice** : un innocent condamné à tort a fini par être réhabilité."}]$ex$::jsonb),
  ('391db6c3-de5d-5a3a-a5f5-7a0cdc56013b'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Ouvrier ou ouvrière : le salaire de la filature","competence":"lire-tableau","situation":"Jeanne feuillette le registre d’une filature en 1890. Elle compare ce que gagnent les hommes et les femmes qui font le même travail.","documents":[{"id":"salaires","type":"tableau","titre":"Salaires par jour dans la filature de Villeroy, 1890","source":"Chiffres imaginés pour l’exercice. F = francs.","colonnes":["Poste","Ouvrier (F par jour)","Ouvrière (F par jour)"],"lignes":[["Fileur / fileuse","3,00","1,50"],["Tisserand / tisseuse","3,20","1,60"],["Bobineur / bobineuse","2,60","1,30"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le salaire journalier d’une **tisseuse**.","aide":"Cherche la ligne « Tisserand / tisseuse », puis la colonne des ouvrières.","type":"zone","document":"salaires","multiple":false},{"enonce":"Combien une tisseuse gagne-t-elle en moins, par jour, qu’un tisserand ?","aide":"Soustrais le salaire de l’ouvrière à celui de l’ouvrier.","type":"nombre","unite":"F"},{"enonce":"Quelle phrase décrit le mieux ce tableau ?","aide":"Compare 1,50 à 3,00 puis 1,30 à 2,60.","type":"choix","options":[{"id":"a","texte":"Pour le même poste, l’ouvrière gagne environ le double de l’ouvrier"},{"id":"b","texte":"Pour le même poste, l’ouvrière gagne le même salaire que l’ouvrier"},{"id":"c","texte":"Pour le même poste, l’ouvrière gagne environ les trois quarts du salaire"},{"id":"d","texte":"Pour le même poste, l’ouvrière gagne environ moitié moins que l’ouvrier"}],"multiple":false},{"enonce":"Une bobineuse travaille 20 jours dans le mois. Combien gagne-t-elle ?","aide":"Multiplie son salaire journalier par 20.","type":"nombre","unite":"F"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c2"]},"explication":"Une tisseuse gagne **1,60 F** par jour : c’est la case située à l’intersection de sa ligne et de la colonne « Ouvrière »."},{"cle":{"type":"nombre","valeur":1.6,"tolerance":0},"affichage":"1,6 F","explication":"3,20 − 1,60 = **1,60 F** de moins chaque jour, pour le même travail."},{"cle":{"type":"choix","ids":["d"]},"explication":"1,50 est la moitié de 3,00 et 1,30 la moitié de 2,60 : les ouvrières gagnent **moitié moins** que les hommes."},{"cle":{"type":"nombre","valeur":26,"tolerance":0},"affichage":"26 F","explication":"1,30 × 20 = **26 F** par mois, alors qu’un bobineur en gagne 52."}]$ex$::jsonb),
  ('391db6c3-de5d-5a3a-a5f5-7a0cdc56013b'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le lycée de jeunes filles","competence":"se-reperer-temps","situation":"En 1881, Mathilde lit l’affiche d’un nouveau lycée pour filles. Sa grand-mère n’a jamais pu faire d’études secondaires. Mathilde cherche ce qui a changé, et à quel rythme.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"Lycée de jeunes filles","sousTitre":"Ouverture à la rentrée d’octobre 1881","emoji":"🏫","lignes":[{"texte":"Ouvert grâce à la loi du 21 décembre 1880","id":"z1","gras":true},{"texte":"Français, histoire, géographie, sciences"},{"texte":"Inscriptions chez la directrice"}],"pied":"Affiche imaginée pour l’exercice."},{"id":"frise","type":"frise","titre":"Les droits des femmes, 1860-1910","debut":1860,"fin":1910,"pas":10,"evenements":[{"id":"z2","date":1861,"nom":"1re bachelière"},{"id":"z3","date":1880,"nom":"Loi Sée"},{"id":"z4","date":1884,"nom":"Divorce"},{"id":"z5","date":1907,"nom":"Salaire libre"}]}],"questions":[{"enonce":"Touche la ligne de l’affiche qui indique le texte de loi permettant d’ouvrir ce lycée.","aide":"Cherche une ligne qui contient une date et le mot « loi ».","type":"zone","document":"affiche","multiple":false},{"enonce":"Julie-Victoire Daubié est la première bachelière de France. Combien d’années avant la loi Sée a-t-elle passé son baccalauréat ?","aide":"Lis les deux dates sur la frise et soustrais-les.","type":"nombre","unite":"ans"},{"enonce":"Range ces quatre avancées du plus ancien au plus récent.","aide":"Suis la frise de gauche à droite.","type":"ordre","items":[{"id":"a","texte":"Salaire disponible pour la femme mariée"},{"id":"b","texte":"Rétablissement du divorce"},{"id":"c","texte":"Première bachelière"},{"id":"d","texte":"Lycées de filles"}]},{"enonce":"Combien d’années séparent le rétablissement du divorce de la loi qui permet aux femmes mariées de disposer de leur salaire ?","aide":"Cherche le divorce puis le salaire sur la frise.","type":"nombre","unite":"ans"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"Le lycée ouvre grâce à la **loi du 21 décembre 1880**, la loi Camille Sée, qui crée les lycées de filles."},{"cle":{"type":"nombre","valeur":19,"tolerance":0},"affichage":"19 ans","explication":"1880 − 1861 = **19 ans** : Daubié a ouvert la voie avant que les lycées de filles n’existent."},{"cle":{"type":"ordre","ids":["c","d","b","a"]},"explication":"**1861 → 1880 → 1884 → 1907** : l’instruction avance d’abord, puis le divorce, et enfin l’argent gagné."},{"cle":{"type":"nombre","valeur":23,"tolerance":0},"affichage":"23 ans","explication":"1907 − 1884 = **23 ans** : l’égalité avance lentement, et le droit de vote n’arrivera qu’en 1944."}]$ex$::jsonb),
  ('391db6c3-de5d-5a3a-a5f5-7a0cdc56013b'::uuid, 3, 3, 15, 50, 4,
   $ex${"titre":"Deux femmes, deux journées vers 1890","competence":"analyser-document","situation":"Pour son exposé, Hugo compare la vie d’une bourgeoise de Lyon et celle d’une ouvrière de filature. Il a un texte et un graphique à croiser.","documents":[{"id":"portraits","type":"texte","genre":"article","titre":"Deux portraits","auteur":"Portraits imaginés pour l’exercice, vers 1890.","blocs":["Louise, 34 ans, épouse d’un notaire à Lyon, ne travaille pas : son mari y tient, car l’oisiveté de sa femme montre la richesse du ménage. Elle dirige deux domestiques, reçoit le jeudi et ne peut signer aucun contrat sans l’autorisation de son mari.","Marie, 29 ans, ouvrière dans une filature, quitte la maison à 5 h 30 et travaille jusqu’à 18 h. Le soir, elle fait le ménage, la cuisine et s’occupe de ses trois enfants. Elle gagne moitié moins que ses collègues masculins : on prétend que son salaire n’est qu’un « appoint »."]},{"id":"heures","type":"graphique","forme":"barres","titre":"Une journée de Louise et de Marie","source":"Heures arrondies, imaginées pour l’exercice (sommeil non compté).","categories":["Travail payé","Tâches de la maison","Repos et loisirs"],"series":[{"nom":"Louise","valeurs":[0,2,7],"teinte":"violet"},{"nom":"Marie","valeurs":[12,3,0],"teinte":"ambre"}],"axeY":{"titre":"Heures par jour","min":0,"max":14,"pas":2},"valeurs":false}],"questions":[{"enonce":"Touche la catégorie dans laquelle **Marie** passe le plus d’heures.","aide":"Cherche la barre la plus haute de la série de Marie.","type":"zone","document":"heures","multiple":false},{"enonce":"Combien d’heures par jour Marie consacre-t-elle à la fois au travail payé et aux tâches de la maison ?","aide":"Additionne les deux premières barres de la série de Marie.","type":"nombre","unite":"heures"},{"enonce":"Touche le mot du texte qui sert à justifier le salaire plus faible des ouvrières.","aide":"Cherche le mot placé entre guillemets à la fin du portrait de Marie.","type":"zone","document":"portraits","multiple":false},{"enonce":"Louise est riche et Marie est pauvre. Qu’ont-elles pourtant en commun d’après le Code civil de 1804 ?","aide":"Pense à ce que Louise ne peut pas faire sans son mari.","type":"choix","options":[{"id":"a","texte":"Elles ont toutes deux le droit de divorcer librement depuis 1816"},{"id":"b","texte":"Elles ont toutes deux obtenu le droit de vote avant 1900"},{"id":"c","texte":"Mariées, elles sont placées sous l’autorité de leur mari"},{"id":"d","texte":"Mariées, elles peuvent toutes deux signer seules un contrat"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k0"]},"explication":"Marie passe **12 heures** en travail payé, à l’usine : c’est la plus grande barre de sa série."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15 heures","explication":"12 + 3 = **15 heures** : c’est la « double journée » des ouvrières, sans aucun repos."},{"cle":{"type":"zone","ids":["m98"]},"explication":"On prétend que le salaire des femmes n’est qu’un **appoint** : c’est un prétexte pour les payer moitié moins."},{"cle":{"type":"choix","ids":["c"]},"explication":"Le Code civil fait de toute femme mariée une **incapable majeure**, riche ou pauvre : la condition des femmes varie selon le milieu, mais le droit les soumet toutes à leur mari."}]$ex$::jsonb),
  ('7f7c0bad-8a3e-50d1-a7f4-815e8facf8e1'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Le basculement de 2007","competence":"lire-graphique","situation":"Inès prépare un exposé sur la ville. Elle trouve un graphique sur la part des citadins dans la population mondiale.","documents":[{"id":"pop","type":"graphique","forme":"barres","titre":"Part de la population mondiale qui vit en ville","source":"Chiffres arrondis, d’après les estimations de l’ONU.","categories":["1950","1970","1990","2007","2020"],"series":[{"nom":"Population urbaine","valeurs":[30,37,43,50,56],"teinte":"violet"}],"axeY":{"titre":"Part des citadins","unite":"en %","min":0,"max":60,"pas":10},"axeX":{"titre":"Année"},"valeurs":false}],"questions":[{"enonce":"Touche l’année où **la moitié** de l’humanité vit en ville.","aide":"Cherche la barre qui atteint 50 % sur l’axe.","type":"zone","document":"pop","multiple":false},{"enonce":"De combien de points la part des citadins a-t-elle augmenté entre 1950 et 2020 ?","aide":"Soustrais la valeur de 1950 à celle de 2020.","type":"nombre","unite":"points"},{"enonce":"Entre 1950 et 2020, la part des citadins…","aide":"30 % puis 56 % : compare 56 au double de 30.","type":"choix","options":[{"id":"a","texte":"a presque doublé"},{"id":"b","texte":"n’a presque pas changé"},{"id":"c","texte":"a été divisée par deux"},{"id":"d","texte":"a triplé"}],"multiple":false}]}$ex$::jsonb,
