   $ex${"titre":"Deux villes de même taille, deux destins","competence":"lire-tableau","situation":"Salomé compare deux villes de quatre millions d’habitants. L’une est un carrefour mondial, l’autre grandit sans être reliée au reste du monde. Elle remplit un tableau et suit la chaîne qui explique la métropolisation.","documents":[{"id":"tab","type":"tableau","titre":"Deux villes de 4 millions d’habitants","source":"Villes imaginées, chiffres inventés pour l’exercice.","colonnes":["Ce qu’on y compte","Ville A","Ville B"],"lignes":[["Vols internationaux par jour",480,12],["Sièges de grandes firmes mondiales",30,1],["Places boursières",1,0],["Ports à conteneurs",2,0]],"enteteLignes":true},{"id":"chaine","type":"chaine","titre":"Le cercle de la métropolisation","disposition":"cycle","noeuds":[{"id":"z1","texte":"Les emplois se concentrent dans la grande ville"},{"id":"z2","texte":"Les jeunes diplômés s’y installent"},{"id":"z3","texte":"?"},{"id":"z4","texte":"La grande ville attire encore plus"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"},{"de":"z4","a":"z1"}]}],"questions":[{"enonce":"Combien de fois la ville A compte-t-elle plus de vols internationaux par jour que la ville B ?","aide":"Divise 480 par 12.","type":"nombre","unite":"fois"},{"enonce":"Que peut-on dire de la ville B ?","aide":"Compare les chiffres des deux colonnes : le nombre d’habitants est le même.","type":"choix","options":[{"id":"a","texte":"Elle est plus riche que la ville A, car elle a moins de vols"},{"id":"b","texte":"Elle compte beaucoup d’habitants mais reste peu reliée aux réseaux mondiaux"},{"id":"c","texte":"Elle est une ville mondiale, car elle compte quatre millions d’habitants"},{"id":"d","texte":"Elle est la plus connectée, car elle n’a ni bourse ni port"}],"multiple":false},{"enonce":"Touche les **deux cases** qui montrent que la ville A pèse dans les décisions et la finance.","aide":"Les décisions se prennent dans les sièges de firmes, les capitaux circulent dans les bourses.","type":"zone","document":"tab","multiple":true},{"enonce":"Que faut-il écrire à la place du « ? » dans le cercle de la métropolisation ?","aide":"Si tout part vers la métropole, que reste-t-il ailleurs ?","type":"choix","options":[{"id":"a","texte":"Les villes moyennes du pays deviennent des métropoles à leur tour"},{"id":"b","texte":"Les villes moyennes du pays gagnent des sièges de grandes firmes"},{"id":"c","texte":"Les villes moyennes du pays perdent des habitants et des emplois"},{"id":"d","texte":"Les villes moyennes du pays reçoivent les capitaux des métropoles"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":40,"tolerance":0},"affichage":"40 fois","explication":"480 ÷ 12 = **40** : la ville A est un hub, la ville B est très peu desservie."},{"cle":{"type":"choix","ids":["b"]},"explication":"La ville B concentre la **population** sans concentrer la richesse : elle est **à l’écart** des réseaux mondiaux."},{"cle":{"type":"zone","ids":["r1c1","r2c1"]},"explication":"Les **sièges de firmes** (30) et la **place boursière** (1) de la ville A prouvent qu’elle décide et qu’elle brasse des capitaux : c’est une ville mondiale."},{"cle":{"type":"choix","ids":["c"]},"explication":"La métropolisation se fait **au détriment des villes moyennes** : emplois, étudiants et capitaux vont vers la grande ville, ce qui la rend encore plus attirante."}]$ex$::jsonb),
  ('e1b2d4a2-9af3-545d-95cd-a8329995a0e7'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Londres et Niamey : qui est relié au monde ?","competence":"analyser-document","situation":"Lucas veut comprendre pourquoi deux villes en croissance ne vivent pas la mondialisation de la même façon. Il lit un réseau simplifié de liaisons aériennes et un récit de deux journées.","documents":[{"id":"reseau","type":"carte","titre":"Un réseau de liaisons aériennes simplifié","fond":"monde","cadrage":[-90,-10,150,62],"source":"Réseau simplifié, écrit pour l’exercice : un trait = une liaison directe.","lieux":[{"id":"z1","lieu":"londres","nom":"Londres","symbole":"etoile","teinte":"violet"},{"id":"z2","lieu":"new-york","nom":"New York","symbole":"etoile","teinte":"violet"},{"id":"z3","lieu":"dubai","nom":"Dubaï","symbole":"etoile","teinte":"violet"},{"id":"z4","lieu":"singapour","nom":"Singapour","symbole":"etoile","teinte":"violet"},{"id":"z5","lieu":"tokyo","nom":"Tokyo","symbole":"etoile","teinte":"violet"},{"id":"z6","lieu":"niamey","nom":"Niamey","symbole":"point","teinte":"ambre"}],"traits":[{"points":["new-york","londres"],"style":"ligne","teinte":"violet"},{"points":["londres","dubai"],"style":"ligne","teinte":"violet"},{"points":["londres","tokyo"],"style":"ligne","teinte":"violet"},{"points":["dubai","singapour"],"style":"ligne","teinte":"violet"},{"points":["singapour","tokyo"],"style":"ligne","teinte":"violet"},{"points":["new-york","tokyo"],"style":"ligne","teinte":"violet"}]},{"id":"recit","type":"texte","genre":"article","titre":"Deux journées","auteur":"Récit imaginé pour l’exercice.","blocs":["À Londres, Sarah dirige une équipe qui travaille chaque jour avec New York et Tokyo. Un vol direct la mène à New York en moins de huit heures, et son entreprise y a un autre siège.","À Niamey, Aïssata étudie l’économie. La ville grandit très vite : de nouveaux quartiers sortent de terre chaque année. Mais pour se rendre à Singapour, il lui faudrait plusieurs escales, et peu d’entreprises internationales y ont un siège."]}],"questions":[{"enonce":"Combien de liaisons directes partent de **Londres** sur la carte ?","aide":"Compte les traits qui touchent le point de Londres.","type":"nombre"},{"enonce":"Touche la ville qui n’est **reliée à aucune autre** sur la carte.","aide":"Cherche le point que ne touche aucun trait.","type":"zone","document":"reseau","multiple":false},{"enonce":"Que montrent ensemble la carte et le récit ?","aide":"Regarde les traits autour de Niamey, puis ce que dit Aïssata sur les entreprises.","type":"choix","options":[{"id":"a","texte":"Londres et Niamey sont toutes les deux également connectées à la mondialisation"},{"id":"b","texte":"Niamey est mieux reliée au monde que Londres, parce que la ville grandit plus vite"},{"id":"c","texte":"Londres est reliée par un vol direct à toutes les villes de la carte, Niamey comprise"},{"id":"d","texte":"Niamey grandit vite mais reste peu reliée aux réseaux mondiaux, à la différence de Londres"}],"multiple":false},{"enonce":"Touche le mot du récit qui montre que Niamey est mal desservie.","aide":"Cherche le mot qui décrit les arrêts nécessaires pour aller à Singapour.","type":"zone","document":"recit","multiple":false},{"enonce":"Complète la phrase sur la métropolisation.","aide":"Pense à ce que cherchent les jeunes diplômés, et à ce que perdent les petites villes.","type":"trous","segments":["Une métropole bien connectée attire des ",0," et des capitaux, souvent au détriment des ",1," de son pays."],"banque":["villes moyennes","ports","emplois","capitales"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":3,"tolerance":0},"affichage":"3","explication":"Londres est reliée à **New York, Dubaï et Tokyo** : trois liaisons."},{"cle":{"type":"zone","ids":["z6"]},"explication":"**Niamey** n’a aucune liaison directe sur le réseau : elle est à l’écart, comme beaucoup de villes d’Afrique subsaharienne."},{"cle":{"type":"choix","ids":["d"]},"explication":"Niamey **concentre la population sans concentrer la richesse** : toutes les grandes villes ne sont pas également connectées à la mondialisation."},{"cle":{"type":"zone","ids":["m65"]},"explication":"Il faut plusieurs **escales** : sans vol direct, la ville est moins reliée au reste du monde."},{"cle":{"type":"trous","trous":[["emplois","emploi"],["villes moyennes","villes moyenne"]]},"affichage":"emplois · villes moyennes","explication":"La métropolisation attire des **emplois** et des capitaux vers la grande ville, au détriment des **villes moyennes** du même pays."}]$ex$::jsonb),
