  ('1545e755-542d-5d56-b483-50163051d583'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Pourquoi partent-ils ? Une enquête","competence":"lire-tableau","situation":"Pour son exposé, Paul a trouvé une enquête menée auprès de 200 migrants arrivés dans une même grande ville. On leur a demandé la raison principale de leur départ.","documents":[{"id":"enquete","type":"tableau","titre":"La raison principale du départ","source":"Enquête imaginée pour l’exercice : 200 personnes interrogées.","colonnes":["Raison du départ","Personnes interrogées"],"lignes":[["Chercher du travail",110],["Fuir une guerre ou une persécution",40],["Rejoindre un proche",30],["Faire des études",10],["Fuir une catastrophe naturelle ou une sécheresse",10]],"enteteLignes":true}],"questions":[{"enonce":"Touche le nombre de personnes qui ont quitté leur pays pour la **raison la plus fréquente**.","aide":"Cherche le plus grand nombre de la colonne de droite.","type":"zone","document":"enquete","multiple":false},{"enonce":"Quel pourcentage des personnes interrogées est parti pour chercher du travail ?","aide":"Divise 110 par 200, puis multiplie par 100.","type":"nombre","unite":"%"},{"enonce":"Combien de personnes ont fui un danger, guerre, persécution ou catastrophe naturelle ?","aide":"Additionne les deux lignes qui parlent de fuir.","type":"nombre","unite":"personnes"},{"enonce":"Quelle phrase résume le mieux cette enquête ?","aide":"Compare la première ligne à la somme de toutes les autres.","type":"choix","options":[{"id":"a","texte":"Plus d’un migrant sur deux part pour chercher du travail"},{"id":"b","texte":"La première raison de partir est de faire des études"},{"id":"c","texte":"La plupart des migrants fuient une guerre ou une persécution"},{"id":"d","texte":"La première raison de partir est de rejoindre un proche"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"**110 personnes** sur 200 sont parties chercher du travail : la cause économique est la cause majoritaire."},{"cle":{"type":"nombre","valeur":55,"tolerance":0},"affichage":"55 %","explication":"110 ÷ 200 = 0,55, soit **55 %** : plus d’un migrant sur deux part pour des raisons économiques."},{"cle":{"type":"nombre","valeur":50,"tolerance":0},"affichage":"50 personnes","explication":"40 + 10 = **50 personnes**, soit un quart de l’échantillon. Les causes environnementales sont en forte hausse dans le monde."},{"cle":{"type":"choix","ids":["a"]},"explication":"Avec 55 %, la raison **économique** domine : on migre d’abord pour travailler, avant de fuir un danger."}]$ex$::jsonb),
