oix","options":[{"id":"a","texte":"Elle vend trop de produits fabriqués dans l’île"},{"id":"b","texte":"Elle dépend d’un secteur très sensible aux crises extérieures"},{"id":"c","texte":"Elle manque de touristes depuis des dizaines d’années"},{"id":"d","texte":"Elle refuse les emplois saisonniers et les hôtels"}],"multiple":false}]}$ex$::jsonb,
