  ('5322f300-a345-53c3-9f13-beb4155b92fb'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"La France, grande puissance maritime","competence":"analyser-document","situation":"Dans son manuel, Romane voit que la France a l’une des plus grandes zones économiques exclusives du monde. Elle ne comprend pas comment un pays de cette taille peut posséder tant de mer. Une carte et un tableau l’aident.","documents":[{"id":"outremer","type":"carte","titre":"Cinq territoires français d’outre-mer","fond":"monde","source":"Territoires choisis pour l’exercice.","lieux":[{"id":"z1","lieu":"papeete","nom":"Polynésie","symbole":"etoile","teinte":"violet"},{"id":"z2","lieu":"noumea","nom":"Nouvelle-Calédonie","symbole":"etoile","teinte":"violet"},{"id":"z3","lieu":"saint-denis-reunion","nom":"La Réunion","symbole":"etoile","teinte":"violet"},{"id":"z4","lieu":"fort-de-france","symbole":"etoile","teinte":"violet"},{"id":"z5","lieu":"cayenne","nom":"Guyane","symbole":"etoile","teinte":"violet"}]},{"id":"zee","type":"tableau","titre":"Les plus grandes zones économiques exclusives","source":"Estimations arrondies : les chiffres varient légèrement selon les sources. 1 mille marin = 1,852 km.","colonnes":["Rang","Pays","ZEE (millions de km²)"],"lignes":[["1","États-Unis","11,4"],["2","France","10,2"],["3","Australie","8,1"],["4","Russie","7,6"],["5","Royaume-Uni","6,8"]],"enteteLignes":true}],"questions":[{"enonce":"Touche le territoire d’outre-mer situé en **Amérique du Sud**.","aide":"Cherche le point au nord-est du continent sud-américain.","type":"zone","document":"outremer","multiple":false},{"enonce":"Combien de ces cinq territoires se trouvent dans l’**océan Pacifique** ?","aide":"Les deux sont sur le bord de la carte, à l’est et à l’ouest du planisphère.","type":"nombre"},{"enonce":"Touche le nom du pays qui possède, d’après ce tableau, la **deuxième ZEE** du monde.","aide":"Lis la colonne « Rang » puis la colonne « Pays ».","type":"zone","document":"zee","multiple":false},{"enonce":"Une ZEE s’étend sur 200 milles marins. Combien cela fait-il de kilomètres, arrondi à la dizaine ? (1 mille marin = 1,852 km)","aide":"Multiplie 200 par 1,852.","type":"nombre","unite":"km"},{"enonce":"Pourquoi la France possède-t-elle une ZEE aussi vaste ?","aide":"Regarde la carte : où sont les territoires français ?","type":"choix","options":[{"id":"a","texte":"Ses territoires d’outre-mer, présents dans tous les océans"},{"id":"b","texte":"Elle a obtenu la mer entière du golfe de Gascogne"},{"id":"c","texte":"Ses côtes de métropole sont les plus longues du monde"},{"id":"d","texte":"La convention de Montego Bay lui a attribué davantage de milles"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"La **Guyane**, sur la côte nord de l’Amérique du Sud, est un territoire français. La Martinique, près d’elle, est dans les Caraïbes."},{"cle":{"type":"nombre","valeur":2,"tolerance":0},"affichage":"2","explication":"**La Polynésie et la Nouvelle-Calédonie** sont dans le Pacifique. La Réunion est dans l’océan Indien, la Martinique et la Guyane dans l’Atlantique."},{"cle":{"type":"zone","ids":["r1c1"]},"explication":"La **France** vient au deuxième rang, après les États-Unis."},{"cle":{"type":"nombre","valeur":370,"tolerance":1},"affichage":"370 km","explication":"200 × 1,852 = 370,4 : une ZEE s’étend sur environ **370 km** au large des côtes."},{"cle":{"type":"choix","ids":["a"]},"explication":"La puissance maritime de la France **ne se lit pas sur la carte de l’Hexagone** : elle vient de ses territoires ultramarins, présents dans l’Atlantique, le Pacifique et l’océan Indien."}]$ex$::jsonb),
  ('7bed8703-f5f0-509a-b427-ced6a778ac29'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"Les villes qui commandent aux États-Unis","competence":"lire-carte","situation":"Tom prépare une fiche sur les États-Unis. Il place sur une carte cinq lieux où se prennent des décisions : finance, pouvoir, numérique, cinéma, énergie.","documents":[{"id":"carte","type":"carte","titre":"Cinq lieux de commandement","fond":"monde","cadrage":[-128,22,-65,50],"source":"Lieux cités dans le cours.","lieux":[{"id":"z1","lieu":"new-york","nom":"New York","symbole":"etoile","teinte":"violet"},{"id":"z2","lieu":"washington","nom":"Washington","symbole":"etoile","teinte":"violet"},{"id":"z3","lieu":"houston","nom":"Houston","symbole":"etoile","teinte":"violet"},{"id":"z4","lieu":"los-angeles","nom":"Los Angeles","symbole":"etoile","teinte":"violet"},{"id":"z5","lon":-122,"lat":37.4,"nom":"Silicon Valley","symbole":"etoile","teinte":"violet"}]}],"questions":[{"enonce":"Touche la ville de **Wall Street** et du siège de l’ONU.","aide":"Cherche la ville de la côte Atlantique, au nord-est.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche les **deux lieux** de la façade Pacifique.","aide":"Cherche les deux étoiles sur la côte ouest.","type":"zone","document":"carte","multiple":true},{"enonce":"Associe chaque lieu à ce qui fait sa puissance.","aide":"Houston est le premier nom qui vient pour le pétrole.","type":"association","gauche":[{"id":"g0","texte":"Washington"},{"id":"g1","texte":"Houston"},{"id":"g2","texte":"Silicon Valley"},{"id":"g3","texte":"Los Angeles"}],"droite":[{"id":"d0","texte":"Le numérique"},{"id":"d1","texte":"Le pétrole et le spatial"},{"id":"d2","texte":"Hollywood et le cinéma"},{"id":"d3","texte":"Le pouvoir politique"}]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z1"]},"explication":"**New York** est le grand centre de la finance (Wall Street) et abrite le siège de l’ONU."},{"cle":{"type":"zone","ids":["z4","z5"]},"explication":"**Los Angeles** (Hollywood) et la **Silicon Valley** (numérique) sont sur la côte du Pacifique, en Californie."},{"cle":{"type":"association","paires":{"g2":"d0","g1":"d1","g3":"d2","g0":"d3"}},"explication":"Chaque lieu a sa **spécialité** : le pouvoir à Washington, l’énergie et le spatial à Houston, le numérique en Silicon Valley, le cinéma à Los Angeles."}]$ex$::jsonb),
  ('7bed8703-f5f0-509a-b427-ced6a778ac29'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le Nord rouillé et le Sud ensoleillé","competence":"lire-carte","situation":"Maëlle découvre que les États-Unis ne se développent pas partout au même rythme. Elle croise une carte de deux grandes régions et un tableau de l’évolution de la population.","documents":[{"id":"carte","type":"carte","titre":"Deux régions américaines","fond":"monde","cadrage":[-128,22,-65,50],"source":"Contours schématiques, dessinés pour l’exercice.","aires":[{"id":"z5","contour":[[-91,40],[-91,45],[-84,46.5],[-76,45],[-71,43],[-73.5,40],[-79,39.8],[-85,38.6],[-89,37.5]],"teinte":"brun","motif":"clair","surTerre":true,"etiquette":"Rust Belt","etiquetteA":[-89,43.3]},{"id":"z6","contour":[[-117.2,32.5],[-114.7,32.7],[-111,31.3],[-108.2,31.3],[-106.5,31.8],[-103,29],[-101,29.8],[-99.5,27.5],[-97.2,25.9],[-90,24.5],[-82,24.2],[-79.5,25],[-75,25.5],[-75,36.6],[-84,36.5],[-90,36.5],[-100,37],[-109,37],[-114,36],[-118,35.5],[-124,35.5],[-124,32.5]],"teinte":"ambre","motif":"clair","surTerre":true,"etiquette":"Sun Belt","etiquetteA":[-98,32]}],"lieux":[{"id":"z1","lon":-83.05,"lat":42.33,"nom":"Detroit","symbole":"point","teinte":"encre"},{"id":"z2","lieu":"houston","nom":"Houston","symbole":"point","teinte":"encre"},{"id":"z3","lieu":"los-angeles","nom":"Los Angeles","symbole":"point","teinte":"encre"},{"id":"z4","lieu":"miami","nom":"Miami","symbole":"point","teinte":"encre"}]},{"id":"pop","type":"tableau","titre":"Évolution de la population de 2010 à 2020","source":"Chiffres arrondis, d’après le recensement américain.","colonnes":["Grande région","Variation (%)"],"lignes":[["Nord-Est","+ 4,1"],["Midwest (dont Detroit)","+ 3,1"],["Sud","+ 10,2"],["Ouest","+ 9,2"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la zone qui représente la **Rust Belt**, la « ceinture de la rouille » de l’ancienne industrie.","aide":"Elle se trouve au nord-est, autour des Grands Lacs.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche les **trois villes** situées dans la Sun Belt.","aide":"Detroit est la seule ville de la carte qui n’appartient pas à la Sun Belt.","type":"zone","document":"carte","multiple":true},{"enonce":"De combien de points la croissance du Sud dépasse-t-elle celle du Midwest, où se trouve Detroit ?","aide":"Soustrais la variation du Midwest à celle du Sud.","type":"nombre","unite":"points"},{"enonce":"Que montrent ensemble la carte et le tableau ?","aide":"Compare la variation du Nord-Est et du Midwest à celle du Sud et de l’Ouest.","type":"choix","options":[{"id":"a","texte":"La population et les activités se déplacent du Nord-Est vers le Sud et l’Ouest"},{"id":"b","texte":"La Sun Belt perd des habitants depuis les années 1970"},{"id":"c","texte":"Les États-Unis se développent à un rythme identique partout"},{"id":"d","texte":"La population croît surtout dans les régions industrielles du Nord-Est"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z5"]},"explication":"La **Rust Belt** est l’ancienne région industrielle du Nord-Est et des Grands Lacs, qui décline depuis les années 1970. Detroit en est le symbole."},{"cle":{"type":"zone","ids":["z2","z3","z4"]},"explication":"**Houston, Los Angeles et Miami** sont dans le Sud et l’Ouest, qui attirent population et activités. Detroit est dans la Rust Belt."},{"cle":{"type":"nombre","valeur":7.1,"tolerance":0},"affichage":"7,1 points","explication":"10,2 − 3,1 = **7,1 points** : la population croît plus de trois fois plus vite dans le Sud."},{"cle":{"type":"choix","ids":["a"]},"explication":"Le Sud et l’Ouest croissent plus vite : c’est le **basculement** du territoire vers la Sun Belt (climat, coûts plus bas, hautes technologies)."}]$ex$::jsonb),
  ('7bed8703-f5f0-509a-b427-ced6a778ac29'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Detroit se vide, Houston grandit","competence":"analyser-document","situation":"Kyle a grandi à Detroit. En 2005, il part pour Houston. Il lit une courbe de population des deux villes et sa propre lettre pour comprendre ce que son départ dit du pays.","documents":[{"id":"courbe","type":"graphique","forme":"courbe","titre":"Population de deux villes américaines","source":"Chiffres arrondis, recensements, communes seules.","categories":["1950","1970","1990","2010","2020"],"series":[{"nom":"Detroit","valeurs":[1.8,1.5,1,0.7,0.6],"teinte":"brun"},{"nom":"Houston","valeurs":[0.6,1.2,1.6,2.1,2.3],"teinte":"ambre"}],"axeY":{"titre":"Habitants","unite":"en millions","min":0,"max":2.5,"pas":0.5},"axeX":{"titre":"Année"}},{"id":"lettre","type":"texte","genre":"lettre","titre":"La lettre de Kyle","auteur":"Texte écrit pour l’exercice.","blocs":["Mon père travaillait dans une usine automobile de Detroit, comme son père avant lui. Quand elle a fermé, le quartier s’est vidé et plusieurs maisons sont restées à l’abandon.","À Houston, j’ai trouvé du travail dans l’énergie et dans l’industrie spatiale. La vie y coûte moins cher et il y fait doux presque toute l’année. Je sais que beaucoup de mes anciens voisins ont fait le même choix."]}],"questions":[{"enonce":"Touche la première date de la courbe où **Houston compte plus d’habitants que Detroit**.","aide":"Cherche l’année où la courbe de Houston passe au-dessus de celle de Detroit.","type":"zone","document":"courbe","multiple":false},{"enonce":"Combien de millions d’habitants Detroit a-t-elle perdus entre 1950 et 2020 ?","aide":"Soustrais la valeur de 2020 à celle de 1950 sur la courbe de Detroit.","type":"nombre","unite":"millions"},{"enonce":"Touche le mot de la lettre qui rappelle une activité de Houston citée dans le cours.","aide":"Houston est liée au pétrole et à une autre industrie de haute technologie.","type":"zone","document":"lettre","multiple":false},{"enonce":"Pourquoi des habitants comme Kyle quittent-ils Detroit pour Houston ?","aide":"La lettre donne trois raisons : le travail, le coût de la vie et le climat.","type":"choix","options":[{"id":"a","texte":"Pour trouver du travail dans des activités en croissance et un climat plus doux"},{"id":"b","texte":"Parce que Detroit est désormais fermée aux nouveaux habitants"},{"id":"c","texte":"Parce que toutes les usines automobiles se sont installées à Houston"},{"id":"d","texte":"Parce que Houston est devenue la capitale politique des États-Unis"}],"multiple":false},{"enonce":"Que montre l’exemple des deux villes sur le territoire des États-Unis ?","aide":"Pense à la phrase du cours sur les inégalités.","type":"choix","options":[{"id":"a","texte":"Que toute l’industrie américaine a disparu partout depuis les années 1950"},{"id":"b","texte":"Que seules les villes du Nord attirent encore les entreprises et les habitants"},{"id":"c","texte":"Qu’il est uniformément riche, de la côte Atlantique à la côte Pacifique"},{"id":"d","texte":"Qu’il est inégal : une grande puissance abrite une région riche et une ville en déclin"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k2"]},"explication":"En **1990**, Houston compte 1,6 million d’habitants contre 1,0 million à Detroit : les deux courbes se sont croisées entre 1970 et 1990."},{"cle":{"type":"nombre","valeur":1.2,"tolerance":0.05},"affichage":"1,2 millions","explication":"1,8 − 0,6 = **1,2 million** d’habitants en moins : Detroit est devenue le symbole du déclin industriel."},{"cle":{"type":"zone","ids":["m45"]},"explication":"Houston est liée au **pétrole** et à l’industrie **spatiale** : deux activités qui attirent des travailleurs dans la Sun Belt."},{"cle":{"type":"choix","ids":["a"]},"explication":"La **Sun Belt** attire : emplois dans l’énergie et le spatial, coûts plus bas, climat doux. Le Nord-Est industriel se vide au contraire."},{"cle":{"type":"choix","ids":["d"]},"explication":"Une puissance mondiale peut avoir, à quelques centaines de kilomètres, une **région parmi les plus riches** et une **ville en faillite** : le territoire n’est pas uniforme."}]$ex$::jsonb),
