   $ex${"titre":"Quatre pays, quatre Afriques","competence":"lire-carte","situation":"Salif prépare un exposé sur l’Afrique. Son professeur lui rappelle que parler de « l’Afrique » comme d’un bloc est un contresens : il lui demande de situer quatre pays très différents.","documents":[{"id":"carte","type":"carte","titre":"Quatre pays africains","fond":"monde","cadrage":[-20,-37,55,38],"reperes":true,"regions":[{"code":"MAR","teinte":"violet","motif":"clair","etiquette":"Maroc"},{"code":"NGA","teinte":"violet","motif":"clair","etiquette":"Nigeria"},{"code":"ETH","teinte":"violet","motif":"clair","etiquette":"Éthiopie"},{"code":"ZAF","teinte":"violet","motif":"clair","etiquette":"Afrique du Sud"}],"regionsCliquables":true,"legende":[{"teinte":"violet","motif":"clair","texte":"Pays cités dans le cours"}]}],"questions":[{"enonce":"Touche le **Nigeria**, pays cité pour son pétrole.","aide":"Il est situé en Afrique de l’Ouest, au fond du golfe de Guinée.","type":"zone","document":"carte","multiple":false},{"enonce":"Touche la **République démocratique du Congo**, pays cité pour son cobalt et son cuivre.","aide":"C’est un très grand pays situé au cœur du continent, de part et d’autre de l’équateur.","type":"zone","document":"carte","multiple":false},{"enonce":"Combien de ces quatre pays coloriés sont situés **au nord de l’équateur** ?","aide":"L’équateur est la ligne en pointillés : un seul pays est entièrement au-dessous.","type":"nombre"}]}$ex$::jsonb,
