  ('10fda032-3e4a-5bc1-a568-17428f3c8b29'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Un continent de plus en plus jeune et peuplé","competence":"lire-graphique","situation":"Amina compare la population africaine d’hier et de demain, et la part des enfants dans la population de trois espaces du monde.","documents":[{"id":"pop","type":"graphique","forme":"barres","titre":"Population de l’Afrique","source":"Chiffres arrondis, d’après l’ONU. 2050 : projection.","categories":["1950","1980","2000","2020","2050"],"series":[{"nom":"Population","valeurs":[230,480,810,1360,2500],"teinte":"ambre"}],"axeY":{"titre":"Habitants","unite":"en millions","min":0,"max":2500,"pas":500},"axeX":{"titre":"Année"},"valeurs":false},{"id":"jeunes","type":"tableau","titre":"Part des moins de 15 ans dans la population","source":"Chiffres arrondis, d’après l’ONU.","colonnes":["Espace","Moins de 15 ans (%)"],"lignes":[["Afrique","40"],["Monde","25"],["Europe","16"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la barre qui est une **projection** pour l’avenir.","aide":"Cherche l’année qui n’est pas encore arrivée.","type":"zone","document":"pop","multiple":false},{"enonce":"De combien de millions d’habitants la population africaine augmenterait-elle entre 2020 et 2050 ?","aide":"Soustrais la valeur de 2020 à celle de 2050.","type":"nombre","unite":"millions"},{"enonce":"Sur 1 000 habitants de l’Afrique, combien ont moins de 15 ans ?","aide":"Calcule 40 % de 1 000.","type":"nombre","unite":"habitants"},{"enonce":"Pourquoi cette jeunesse est-elle à la fois un défi et un atout ?","aide":"Pense à ce dont ont besoin des enfants nombreux, puis à ce qu’ils deviendront.","type":"choix","options":[{"id":"a","texte":"Elle ralentit la croissance, car elle n’a besoin d’aucun service public"},{"id":"b","texte":"Il faut fermer des écoles et des collèges, car les retraités sont très nombreux"},{"id":"c","texte":"Il faut des écoles, des emplois et des logements, mais la main-d’œuvre est immense"},{"id":"d","texte":"Elle empêche toute urbanisation ainsi que tout développement du commerce"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["k4"]},"explication":"La barre de **2050** est une projection : l’ONU estime que la population pourrait avoisiner 2,5 milliards."},{"cle":{"type":"nombre","valeur":1140,"tolerance":50},"affichage":"1140 millions","explication":"2 500 − 1 360 = **1 140 millions**, presque autant que toute la population actuelle du continent."},{"cle":{"type":"nombre","valeur":400,"tolerance":0},"affichage":"400 habitants","explication":"1 000 × 40 ÷ 100 = **400 habitants** : l’Afrique est le continent le plus jeune."},{"cle":{"type":"choix","ids":["c"]},"explication":"Beaucoup de jeunes demandent **écoles, emplois et logements** ; mais ils formeront aussi une **main-d’œuvre et un marché** immenses."}]$ex$::jsonb),
  ('10fda032-3e4a-5bc1-a568-17428f3c8b29'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Du minerai congolais à la batterie","competence":"analyser-document","situation":"Un cargo quitte la République démocratique du Congo avec du cobalt brut. Élise suit la route du minerai et les valeurs ajoutées à chaque étape, pour comprendre pourquoi l’Afrique exporte beaucoup mais gagne peu.","documents":[{"id":"chaine","type":"chaine","titre":"Du minerai à la voiture","disposition":"colonne","noeuds":[{"id":"z1","texte":"Mine de cobalt, République démocratique du Congo","emoji":"⛏️"},{"id":"z2","texte":"Minerai exporté brut","emoji":"🚢"},{"id":"z3","texte":"Raffinage dans un autre pays","emoji":"🏭"},{"id":"z4","texte":"Batterie et voiture fabriquées ailleurs","emoji":"🚗"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]},{"id":"valeur","type":"tableau","titre":"Où se crée la valeur d’une batterie ?","source":"Répartition imaginée pour l’exercice.","colonnes":["Étape","Part de la valeur finale"],"lignes":[["Extraction du minerai","5 %"],["Raffinage","20 %"],["Fabrication de la batterie","45 %"],["Montage du véhicule et vente","30 %"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la part de la valeur qui reste dans le **pays qui extrait** le minerai.","aide":"Le pays producteur ne fait que la première étape.","type":"zone","document":"valeur","multiple":false},{"enonce":"Une batterie vaut 6 000 €. Combien de cette valeur correspond à l’extraction du minerai ?","aide":"Calcule 5 % de 6 000.","type":"nombre","unite":"€"},{"enonce":"Quelle part de la valeur finale est créée par les deux étapes de **transformation** (raffinage et fabrication de la batterie) ?","aide":"Additionne les deux lignes concernées.","type":"nombre","unite":"%"},{"enonce":"Touche l’étape du trajet où le minerai quitte l’Afrique **sans avoir été transformé**.","aide":"Cherche l’étape qui nomme le minerai « brut » et un navire.","type":"zone","document":"chaine","multiple":false},{"enonce":"Quelle phrase résume le mieux la situation ?","aide":"Compare les 5 % de l’extraction à la valeur d’une batterie finie.","type":"choix","options":[{"id":"a","texte":"Les pays africains transforment déjà la plupart de leurs minerais sur place"},{"id":"b","texte":"Le prix de la batterie est fixé uniquement par le pays qui extrait le minerai"},{"id":"c","texte":"Exporter un minerai brut, c’est vendre au prix de la matière et acheter l’objet fini au prix du travail"},{"id":"d","texte":"Exporter un minerai brut rapporte toujours plus que fabriquer la batterie sur place"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1"]},"explication":"L’extraction ne représente que **5 %** de la valeur finale : le pays qui exporte son minerai brut garde très peu de la richesse créée."},{"cle":{"type":"nombre","valeur":300,"tolerance":0},"affichage":"300 €","explication":"6 000 × 5 ÷ 100 = **300 €** seulement."},{"cle":{"type":"nombre","valeur":65,"tolerance":0},"affichage":"65 %","explication":"20 + 45 = **65 %** : l’essentiel de la valeur se crée après l’extraction, **ailleurs**."},{"cle":{"type":"zone","ids":["z2"]},"explication":"Le **minerai exporté brut** part tel quel : la transformation, donc l’essentiel de la valeur, se fait ailleurs."},{"cle":{"type":"choix","ids":["c"]},"explication":"Vendre brut, c’est vendre au **prix de la matière** ; l’objet fini s’achète au **prix du travail**. D’où l’enjeu de transformer sur place."}]$ex$::jsonb),
  ('a66ae76b-4466-413f-8dde-c05c0a645e9d'::uuid, 1, 1, 5, 20, 3,
