   $ex${"titre":"Le chien aboie dans le jardin","competence":"comprendre-langue","situation":"Inès lit un petit récit en latin : une jeune fille se promène, puis il se passe quelque chose. Elle doit repérer les temps pour comprendre le décor et l’action.","documents":[{"id":"texte","type":"texte","genre":"recit","titre":"Un petit récit","auteur":"Phrases écrites pour l’exercice","blocs":["Puella in horto ambulabat.","Subito canis latravit.","Dum puer legebat, pater intravit."]},{"id":"voc","type":"tableau","titre":"Vocabulaire","colonnes":["Latin","Français"],"lignes":[["puella","la jeune fille"],["hortus","le jardin"],["ambulare","marcher"],["subito","soudain"],["canis","le chien"],["latrare","aboyer"],["puer","le garçon"],["legere","lire"],["pater","le père"],["intrare","entrer"]]}],"questions":[{"enonce":"Touche le verbe qui plante le décor dans la phrase 1.","aide":"Cherche la marque -ba-.","type":"zone","document":"texte","multiple":false},{"enonce":"Classe ces quatre verbes du récit selon leur temps.","aide":"Cherche la marque -ba- ; pour le parfait, regarde la finale -vit.","type":"categories","categories":[{"id":"c0","texte":"Imparfait"},{"id":"c1","texte":"Parfait"}],"items":[{"id":"i0","texte":"legebat"},{"id":"i1","texte":"intravit"},{"id":"i2","texte":"latravit"},{"id":"i3","texte":"ambulabat"}]},{"enonce":"Quelle est la traduction des phrases 1 et 2 ?","aide":"Un verbe à l’imparfait se traduit par un imparfait, un verbe au parfait par un passé simple.","type":"choix","options":[{"id":"a","texte":"Le chien marchait dans le jardin. Soudain, la jeune fille aboya."},{"id":"b","texte":"La jeune fille marcha dans le jardin. Soudain, le chien aboya."},{"id":"c","texte":"La jeune fille marchait dans le jardin. Soudain, le chien aboya."},{"id":"d","texte":"La jeune fille marchera dans le jardin. Soudain, le chien aboiera."}],"multiple":false},{"enonce":"Complète la traduction de la phrase 3.","aide":"Le verbe à l’imparfait décrit, le verbe au parfait annonce l’action.","type":"trous","segments":["Pendant que le garçon ",0,", son père ",1,"."],"banque":["lisait","entra","entrait","lut"]}]}$ex$::jsonb,
