   $ex${"titre":"Au secours, un cri dans la rue !","competence":"analyser-texte","situation":"Inès traduit un récit en quatre phrases. Pour comprendre l’histoire, elle doit distinguer ce qui dure de ce qui arrive d’un coup, et connaître le parfait de quelques verbes.","documents":[{"id":"recit","type":"texte","genre":"recit","titre":"Dans la rue","auteur":"Récit écrit pour l’exercice","blocs":["Marcus in via ambulabat et cantabat.","Subito puella clamavit.","Lupus in silva stabat.","Marcus ad puellam cucurrit."],"source":"Vocabulaire : via = route ; cantare = chanter ; clamare = crier ; lupus = loup ; silva = forêt ; stare = se tenir ; ad = vers ; currere = courir."},{"id":"temps","type":"tableau","titre":"Présent et parfait de quatre verbes","colonnes":["Verbe","Présent","Parfait"],"lignes":[["marcher","ambulo","ambulavi"],["crier","clamo","clamavi"],["courir","curro","cucurri"],["chanter","canto","cantavi"]]}],"questions":[{"enonce":"Dans la phrase 1, touche les deux verbes à l’imparfait.","aide":"Cherche la marque -ba- dans les deux verbes.","type":"zone","document":"recit","multiple":true},{"enonce":"Dans le tableau, touche le parfait dont le radical est redoublé.","aide":"Un redoublement répète le début du radical.","type":"zone","document":"temps","multiple":false},{"enonce":"Remets dans l’ordre les actions de Marcus.","aide":"Suis l’ordre des phrases du récit.","type":"ordre","items":[{"id":"a","texte":"Marcus chante sur la route"},{"id":"b","texte":"Marcus court vers elle"},{"id":"c","texte":"Une jeune fille crie"}]},{"enonce":"Pourquoi « stabat » est-il à l’imparfait ?","aide":"Se tenir quelque part dure : ce n’est pas un événement.","type":"choix","options":[{"id":"a","texte":"Il annonce ce qui va arriver plus tard"},{"id":"b","texte":"Il exprime un ordre donné à quelqu’un"},{"id":"c","texte":"Il rapporte une action brève et achevée"},{"id":"d","texte":"Il décrit le décor : le loup se tient là"}],"multiple":false},{"enonce":"Associe chaque verbe latin à sa traduction.","aide":"Imparfait : « il … ait » ; parfait : passé simple.","type":"association","gauche":[{"id":"g0","texte":"ambulabat"},{"id":"g1","texte":"clamavit"},{"id":"g2","texte":"cucurrit"},{"id":"g3","texte":"stabat"}],"droite":[{"id":"d0","texte":"il se tenait"},{"id":"d1","texte":"il cria"},{"id":"d2","texte":"il courut"},{"id":"d3","texte":"il marchait"}]}]}$ex$::jsonb,
