  ('bbc8df26-d175-58d1-affb-8efd8a429819'::uuid, 1, 1, 5, 20, 3,
   $ex${"titre":"La nuit glaciale de la station","competence":"calculer","situation":"À la station de Morzine, la température a baissé de 3 °C chaque heure pendant toute la nuit. Le gardien de la station note sa variation depuis minuit dans un tableau.","documents":[{"id":"releve","type":"tableau","titre":"Variation de la température depuis minuit","source":"Relevé inventé pour l’exercice","colonnes":["Heures écoulées","1","2","3","4","5"],"lignes":[["Variation (°C)",-3,-6,-9,"?",-15]],"enteteLignes":true}],"questions":[{"enonce":"Quelle est la variation de température au bout de **4 heures** ? (la case « ? » du tableau)","aide":"Chaque heure apporte −3 °C. Pour 4 heures, on multiplie −3 par 4 : un négatif fois un positif.","type":"nombre","unite":"°C"},{"enonce":"La nuit dure 8 heures de plus. Quelle serait la variation totale au bout de **8 heures** ?","aide":"Reprends le coefficient du tableau : −3 °C par heure.","type":"nombre","unite":"°C"},{"enonce":"Au bout de combien d’heures la variation atteint-elle **−27 °C** ?","aide":"On cherche le nombre d’heures h tel que (−3) × h = −27 : c’est une division.","type":"nombre","unite":"heures"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":-12,"tolerance":0},"affichage":"−12 °C","explication":"Une baisse de 3 °C chaque heure, pendant 4 heures : (−3) × 4. Signes contraires, donc le résultat est négatif : 3 × 4 = 12, soit **−12 °C**."},{"cle":{"type":"nombre","valeur":-24,"tolerance":0},"affichage":"−24 °C","explication":"(−3) × 8 : signes contraires donc négatif, et 3 × 8 = 24. La variation est de **−24 °C**."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9 heures","explication":"(−27) ÷ (−3) : deux signes identiques donnent un quotient positif, et 27 ÷ 3 = 9. Il faut **9 heures**."}]$ex$::jsonb),
  ('bbc8df26-d175-58d1-affb-8efd8a429819'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le score de Léo, piège après piège","competence":"calculer","situation":"Dans son jeu vidéo, Léo perd des points quand il touche un piège et en gagne quand il ramasse une étoile. Il a joué une partie complète et note son bilan.","documents":[{"id":"bilan","type":"tableau","titre":"Le bilan de la partie","source":"Barème inventé pour l’exercice","colonnes":["Événement","Points par fois","Nombre de fois","Total"],"lignes":[["Piège touché",-6,4,"?"],["Étoile ramassée",5,7,"?"]],"enteteLignes":true}],"questions":[{"enonce":"Quel est le total des points des **pièges** touchés ?","aide":"Chaque piège vaut −6 points ; il y en a 4. Un nombre négatif multiplié par un positif donne…","type":"nombre"},{"enonce":"Quel est le total des points des **étoiles** ?","aide":"Ici, les deux nombres sont positifs.","type":"nombre"},{"enonce":"Léo commençait à 0 point. Quel est son **score final** ?","aide":"Additionne les deux totaux, le négatif et le positif.","type":"nombre"},{"enonce":"Léo ramasse 35 points d’étoiles. Combien de **pièges** peut-il toucher au maximum sans que son score devienne négatif ?","aide":"Compare 6 × (nombre de pièges) à 35 : il ne faut pas dépasser 35.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":-24,"tolerance":0},"affichage":"−24","explication":"4 pièges à −6 points : (−6) × 4 = **−24** (signes contraires, résultat négatif)."},{"cle":{"type":"nombre","valeur":35,"tolerance":0},"affichage":"35","explication":"5 × 7 = **35** points : deux facteurs positifs, un produit positif."},{"cle":{"type":"nombre","valeur":11,"tolerance":0},"affichage":"11","explication":"−24 + 35 = **11** points : les gains l’emportent sur les pertes."},{"cle":{"type":"nombre","valeur":5,"tolerance":0},"affichage":"5","explication":"Chaque piège coûte 6 points. 5 pièges : 5 × 6 = 30 ≤ 35, le score reste positif. 6 pièges : 36 > 35, le score serait −1. Le maximum est **5 pièges**."}]$ex$::jsonb),
  ('bbc8df26-d175-58d1-affb-8efd8a429819'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Inès et Malo ne sont pas d’accord","competence":"raisonner","situation":"Inès et Malo corrigent des calculs sur les puissances et les produits de relatifs. Ils ne trouvent pas les mêmes résultats : il faut les départager, puis vérifier le cahier de Malo.","documents":[{"id":"dial","type":"dialogue","modele":"bulles","titre":"La dispute","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Malo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"(−2)³, c’est (−2) × 3, donc −6."},{"qui":"Malo","texte":"Non, c’est (−2) × (−2) × (−2). Je trouve −8."},{"qui":"Inès","texte":"Et −2², le carré rend toujours positif : ça fait 4."},{"qui":"Malo","texte":"Là, le carré ne porte que sur le 2 : je trouve −4."}]},{"id":"cahier","type":"tableau","titre":"Le cahier de Malo","source":"Calculs écrits pour l’exercice","colonnes":["Calcul","Résultat de Malo"],"lignes":[["(−7) × 3","−21"],["(−4) × (−5) × (−1)","20"],["(−36) ÷ (−4)","−9"],["−5²","−25"]],"enteteLignes":true}],"questions":[{"enonce":"Pour **(−2)³**, qui a raison ?","aide":"Une puissance d’exposant 3 répète trois fois le même facteur.","type":"choix","options":[{"id":"a","texte":"Malo : il écrit trois facteurs égaux à −2"},{"id":"b","texte":"Inès : elle multiplie −2 par 3"},{"id":"c","texte":"Les deux, car −6 et −8 sont égaux"},{"id":"d","texte":"Aucun des deux : la réponse est positive"}],"multiple":false},{"enonce":"Pour **−2²**, qui a raison ?","aide":"Regarde où se trouvent les parenthèses : dans −2², le signe moins est-il élevé au carré ?","type":"choix","options":[{"id":"a","texte":"Aucun des deux : le résultat est 0"},{"id":"b","texte":"Inès, car un carré est toujours positif"},{"id":"c","texte":"Malo, car le carré ne porte que sur le 2"},{"id":"d","texte":"Les deux, car 4 et −4 sont opposés"}],"multiple":false},{"enonce":"Touche les **deux résultats faux** dans le cahier de Malo.","aide":"Refais chaque calcul : combien de facteurs négatifs, et donc quel signe ?","type":"zone","document":"cahier","multiple":true},{"enonce":"Quel est le **vrai résultat** de (−4) × (−5) × (−1) ?","aide":"Compte les facteurs négatifs : pair, produit positif ; impair, produit négatif.","type":"nombre"},{"enonce":"Quelle est la valeur de **(−2)⁴** ?","aide":"Quatre facteurs égaux à −2 : (−2) × (−2) × (−2) × (−2). Combien de facteurs négatifs ?","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["a"]},"explication":"a³ = a × a × a. Donc (−2)³ = (−2) × (−2) × (−2) : (−2) × (−2) = 4 puis 4 × (−2) = −8. **Malo a raison.**"},{"cle":{"type":"choix","ids":["c"]},"explication":"Sans parenthèses, le carré ne porte que sur 2 : −2² = −(2 × 2) = **−4**. Avec parenthèses, (−2)² = 4. **Malo a raison.**"},{"cle":{"type":"zone","ids":["r1c1","r2c1"]},"explication":"(−4) × (−5) × (−1) a **3 facteurs négatifs** (nombre impair) : le résultat est négatif, −20 et non 20. (−36) ÷ (−4) : deux signes identiques, résultat **+9** et non −9."},{"cle":{"type":"nombre","valeur":-20,"tolerance":0},"affichage":"−20","explication":"Trois facteurs négatifs : le produit est négatif. 4 × 5 × 1 = 20, donc **−20**."},{"cle":{"type":"nombre","valeur":16,"tolerance":0},"affichage":"16","explication":"Quatre facteurs négatifs : nombre pair, donc produit positif. 2 × 2 × 2 × 2 = 16, soit **16**. Plus généralement, une puissance paire d’un négatif est positive."}]$ex$::jsonb),
