d":"c","texte":"{{3/4}}"},{"id":"d","texte":"{{9/10}}"}],"multiple":false},{"enonce":"Par quel nombre divise-t-on 9 et 12 pour obtenir {{3/4}} ?","aide":"9 ÷ ? = 3.","type":"nombre"}]}$ex$::jsonb,
