  ('6d35af41-354f-52e9-b68a-ffc87011d036'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Les gobelets de la colonie","competence":"calculer","situation":"À la colonie, cinq gobelets sont remplis de jus de fruit. Chaque moniteur a noté la fraction de gobelet remplie, avec des écritures différentes.","documents":[{"id":"gobelets","type":"tableau","titre":"Contenu des gobelets","source":"Relevé inventé pour l’exercice","colonnes":["Gobelet","Fraction remplie"],"lignes":[["A","{{6/8}}"],["B","{{9/12}}"],["C","{{4/6}}"],["D","{{10/15}}"],["E","{{15/20}}"]],"enteteLignes":true}],"questions":[{"enonce":"Classe chaque gobelet selon la **quantité de jus** qu’il contient.","aide":"Simplifie chaque fraction du tableau jusqu’à ne plus pouvoir.","type":"categories","categories":[{"id":"c0","texte":"Autant que {{3/4}}"},{"id":"c1","texte":"Autant que {{2/3}}"}],"items":[{"id":"i0","texte":"Gobelet B"},{"id":"i1","texte":"Gobelet C"},{"id":"i2","texte":"Gobelet E"},{"id":"i3","texte":"Gobelet A"},{"id":"i4","texte":"Gobelet D"}]},{"enonce":"Complète l’égalité du gobelet A : 6/8 = 3/___ = 12/___.","aide":"De 6 à 3, on divise par 2. Pour 12, on multiplie 6 par 2.","type":"trous","segments":["6/8 = 3/",0," = 12/",1]},{"enonce":"Le gobelet **B** contient-il plus de jus que le gobelet **D** ?","aide":"Réduis {{3/4}} et {{2/3}} au même dénominateur 12.","type":"choix","options":[{"id":"a","texte":"Non, car ils sont égaux"},{"id":"b","texte":"Non, car D en contient plus"},{"id":"c","texte":"Oui, car {{3/4}} > {{2/3}}"},{"id":"d","texte":"On ne peut pas savoir"}],"multiple":false},{"enonce":"Un gobelet de 240 mL est rempli aux {{3/4}}. Combien de mL de jus contient-il ?","aide":"Divise 240 par 4 pour obtenir un quart.","type":"nombre","unite":"mL"}]}$ex$::jsonb,
