  ('6d35af41-354f-52e9-b68a-ffc87011d036'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Agrandir sans déformer","competence":"raisonner","situation":"Nour imprime des photos au même format que l’original pour son exposition. Elle compare les formats proposés par l’imprimeur, et Tim et Emma se disputent sur une méthode.","documents":[{"id":"formats","type":"tableau","titre":"Les formats de l’imprimeur (en cm)","source":"Formats inventés pour l’exercice","colonnes":["Format","Largeur","Hauteur"],"lignes":[["A",10,15],["B",12,18],["C",8,10],["D",14,21]],"enteteLignes":true},{"id":"dial","type":"dialogue","modele":"bulles","titre":"La méthode de Tim","participants":[{"nom":"Tim","emoji":"👦","cote":"gauche"},{"nom":"Emma","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Tim","texte":"Le format C fait 8 sur 10. J’ajoute 4 en haut et en bas : 12 sur 14, c’est la même forme !"},{"qui":"Emma","texte":"Je ne crois pas. On ne peut pas ajouter pareil aux deux."}]}],"questions":[{"enonce":"Touche les formats qui ont **la même forme** que le format A (même rapport largeur ÷ hauteur).","aide":"Compare les fractions {{10/15}}, {{12/18}}, {{8/10}} et {{14/21}} : simplifie-les.","type":"zone","document":"formats","multiple":true},{"enonce":"On agrandit le format A pour qu’il ait une largeur de **24 cm**. Quelle est sa hauteur ?","aide":"Cherche h tel que {{10/15}} = {{24/h}} : par quoi multiplie-t-on 10 pour obtenir 24 ?","type":"nombre","unite":"cm"},{"enonce":"On agrandit le format C pour qu’il ait une hauteur de **25 cm**. Quelle est sa largeur ?","aide":"{{8/10}} = {{x/25}} : par quoi multiplie-t-on 10 pour obtenir 25 ?","type":"nombre","unite":"cm"},{"enonce":"Qui a raison, Tim ou Emma ?","aide":"Qu’a-t-on le droit de faire avec le numérateur et le dénominateur pour garder la même fraction ?","type":"choix","options":[{"id":"a","texte":"Aucun des deux : il faut soustraire 4"},{"id":"b","texte":"Tim : ajouter 4 en haut et en bas suffit"},{"id":"c","texte":"Emma : on n’ajoute pas, on multiplie ou divise"},{"id":"d","texte":"Les deux, car {{8/10}} et {{12/14}} sont proches"}],"multiple":false},{"enonce":"Vérifie avec le produit en croix : calcule 12 × 10 − 8 × 14. Si les fractions étaient égales, on trouverait 0.","aide":"Calcule chaque produit séparément : 12 × 10 et 8 × 14.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r1c0","r3c0"]},"explication":"{{10/15}} = {{2/3}} ; {{12/18}} = {{2/3}} ; {{14/21}} = {{2/3}} ; mais {{8/10}} = {{4/5}}. Les formats **B et D** ont la même forme que A."},{"cle":{"type":"nombre","valeur":36,"tolerance":0},"affichage":"36 cm","explication":"Produit en croix : 10 × h = 15 × 24 = 360, donc h = 36. La hauteur est de **36 cm**."},{"cle":{"type":"nombre","valeur":20,"tolerance":0},"affichage":"20 cm","explication":"10 × x = 8 × 25 = 200, donc x = 20. La largeur est de **20 cm** (et {{8/10}} = {{20/25}})."},{"cle":{"type":"choix","ids":["c"]},"explication":"Seules la **multiplication** et la **division** par un même nombre conservent la valeur. En ajoutant 4, on passe de {{8/10}} à {{12/14}}, qui n’est pas égale."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8","explication":"12 × 10 = 120 et 8 × 14 = 112. L’écart vaut **8**, différent de 0 : {{8/10}} et {{12/14}} ne sont pas égales, Emma a raison."}]$ex$::jsonb),
