  ('105df279-2f8a-5b37-a20c-e5cd54cd33ab'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Les erreurs du cahier de Noé","competence":"raisonner","situation":"Noé a fait des calculs avec des fractions et a eu quelques bonnes surprises. Emma, qui relit son cahier, pense que plusieurs résultats sont faux.","documents":[{"id":"cahier","type":"tableau","titre":"Le cahier de Noé","source":"Calculs écrits pour l’exercice","colonnes":["Calcul","Résultat de Noé"],"lignes":[["{{2/3}} + {{1/4}}","{{3/7}}"],["{{4/9}} × {{3/8}}","{{1/6}}"],["{{3/4}} ÷ {{9/8}}","{{27/32}}"],["{{5/6}} − {{1/4}}","{{7/12}}"]],"enteteLignes":true},{"id":"dial","type":"dialogue","modele":"bulles","titre":"Noé explique sa méthode","participants":[{"nom":"Noé","emoji":"👦","cote":"gauche"},{"nom":"Emma","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Noé","texte":"Pour additionner, j’additionne en haut et en bas : (2 + 1) sur (3 + 4)."},{"qui":"Emma","texte":"3/7 est plus petit que 2/3, alors que tu as AJOUTÉ un nombre. Bizarre, non ?"},{"qui":"Noé","texte":"Pour diviser, je fais comme pour multiplier : 3 × 9 sur 4 × 8."}]}],"questions":[{"enonce":"Touche les **deux résultats faux** dans le cahier de Noé.","aide":"Vérifie chaque calcul. Pour une addition, le résultat ne peut pas être plus petit que les deux termes.","type":"zone","document":"cahier","multiple":true},{"enonce":"Quel est le **bon résultat** de {{2/3}} + {{1/4}} ? (une fraction, ou un décimal arrondi au centième)","aide":"Réduis au même dénominateur 12, puis additionne les numérateurs.","type":"nombre"},{"enonce":"Quel est le **bon résultat** de {{3/4}} ÷ {{9/8}} ? (une fraction, ou un décimal arrondi au centième)","aide":"Diviser par {{9/8}}, c’est multiplier par son inverse.","type":"nombre"},{"enonce":"Quelle est l’erreur de Noé dans la **division** ?","aide":"Compare son calcul 3 × 9 sur 4 × 8 avec une multiplication ordinaire.","type":"choix","options":[{"id":"a","texte":"Il multiplie par la fraction au lieu de son inverse"},{"id":"b","texte":"Il inverse les deux fractions"},{"id":"c","texte":"Il oublie de réduire au même dénominateur"},{"id":"d","texte":"Il divise seulement les numérateurs"}],"multiple":false},{"enonce":"Calcule {{2/3}} − {{1/2}} × {{1/3}} (priorités opératoires). Donne le résultat en décimal.","aide":"La multiplication passe avant la soustraction.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1","r2c1"]},"explication":"{{2/3}} + {{1/4}} = {{8/12}} + {{3/12}} = {{11/12}}, pas {{3/7}}. {{3/4}} ÷ {{9/8}} = {{3/4}} × {{8/9}} = {{2/3}}, pas {{27/32}}. Les deux autres calculs sont justes."},{"cle":{"type":"nombre","valeur":0.9166666666666666,"tolerance":0.005},"affichage":"0,9167","explication":"{{2/3}} = {{8/12}} et {{1/4}} = {{3/12}} : {{8/12}} + {{3/12}} = {{11/12}}. On ne touche pas au dénominateur commun."},{"cle":{"type":"nombre","valeur":0.6666666666666666,"tolerance":0.005},"affichage":"0,6667","explication":"{{3/4}} ÷ {{9/8}} = {{3/4}} × {{8/9}} = {{24/36}} = {{2/3}}. Noé a multiplié par {{9/8}} au lieu de son inverse."},{"cle":{"type":"choix","ids":["a"]},"explication":"Noé calcule {{3/4}} × {{9/8}} = {{27/32}} : c’est une **multiplication**. Pour diviser, il faut multiplier par l’**inverse** {{8/9}}."},{"cle":{"type":"nombre","valeur":0.5,"tolerance":0},"affichage":"0,5","explication":"On calcule d’abord {{1/2}} × {{1/3}} = {{1/6}}, puis {{2/3}} − {{1/6}} = {{4/6}} − {{1/6}} = {{3/6}} = {{1/2}}, soit **0,5**."}]$ex$::jsonb),
