   $ex$[{"cle":{"type":"nombre","valeur":8000000000,"tolerance":0},"affichage":"8 000 000 000 octets","explication":"10⁹ = 1 000 000 000, donc 8 × 10⁹ = **8 000 000 000** octets."},{"cle":{"type":"trous","trous":[["go"],["to"]]},"affichage":"Go · To","explication":"10⁹ octets, c’est un **giga**-octet : 8 × 10⁹ octets = 8 Go. 10¹² octets, c’est un **téra**-octet : 2 × 10¹² octets = 2 To."},{"cle":{"type":"choix","ids":["b"]},"explication":"2 × 10¹² est un nombre à 13 chiffres, alors que 32 × 10⁹ n’en a que 11. Le **disque dur** a la plus grande capacité."}]$ex$::jsonb),
