","type":"choix","options":[{"id":"a","texte":"Le tarif B : 40 € contre 48 € au tarif A"},{"id":"b","texte":"Aucune différence : 12 séances suffisent"},{"id":"c","texte":"Le tarif A : 48 € contre 44 € au tarif B"},{"id":"d","texte":"Le tarif B : 44 € contre 48 € au tarif A"}],"multiple":false}]}$ex$::jsonb,
