  ('33562b41-7711-5225-8fc3-9d1e10b7713a'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Le produit nul de Théo","competence":"raisonner","situation":"En résolvant (x − 3)(x + 4) = 0, Théo n’a trouvé qu’une solution. Maya pense qu’il en manque. Pour trancher, ils testent quelques valeurs de x.","documents":[{"id":"dial","type":"dialogue","modele":"bulles","titre":"La discussion","participants":[{"nom":"Théo","emoji":"👦","cote":"gauche"},{"nom":"Maya","emoji":"👧","cote":"droite"}],"repliques":[{"qui":"Théo","texte":"x − 3 = 0, donc x = 3. L’équation n’a qu’une solution."},{"qui":"Maya","texte":"Un produit est nul quand l’un des facteurs l’est. Et l’autre facteur ?"}]},{"id":"essais","type":"tableau","titre":"Les essais","colonnes":["x","−4","0","3","4"],"lignes":[["(x − 3)(x + 4)",0,-12,0,8]],"enteteLignes":true}],"questions":[{"enonce":"Touche les valeurs de x pour lesquelles le produit **vaut 0**.","aide":"Cherche les cases égales à 0 dans la dernière ligne.","type":"zone","document":"essais","multiple":true},{"enonce":"Qui a raison ?","aide":"Une équation produit nul : A × B = 0 donne A = 0 ou B = 0.","type":"choix","options":[{"id":"a","texte":"Théo : 3 est la seule solution"},{"id":"b","texte":"Maya : il y a deux solutions, 3 et −4"},{"id":"c","texte":"Les deux : 3 est une solution"},{"id":"d","texte":"Aucun : l’équation n’a pas de solution"}],"multiple":false},{"enonce":"Résous 5x − 7 = 3x + 9. Combien vaut x ?","aide":"Regroupe les x à gauche et les nombres à droite : 5x − 3x = 9 + 7.","type":"nombre"},{"enonce":"Résous 3(x − 4) = x + 6. Combien vaut x ?","aide":"Développe d’abord : 3(x − 4) = 3x − 12.","type":"nombre"},{"enonce":"Combien de solutions a l’équation 4x + 5 = 4(x + 2) ?","aide":"Développe le membre de droite, puis soustrais 4x des deux côtés.","type":"choix","options":[{"id":"a","texte":"Exactement deux"},{"id":"b","texte":"Aucune"},{"id":"c","texte":"Une infinité"},{"id":"d","texte":"Une seule : x = 0"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c1","r0c3"]},"explication":"Le produit vaut 0 pour **x = −4** et pour **x = 3**."},{"cle":{"type":"choix","ids":["b"]},"explication":"x − 3 = 0 donne x = 3 et x + 4 = 0 donne x = −4. Il y a **deux** solutions : Maya a raison."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8","explication":"5x − 3x = 9 + 7, donc 2x = 16 et x = **8**. Vérification : 5 × 8 − 7 = 33 et 3 × 8 + 9 = 33."},{"cle":{"type":"nombre","valeur":9,"tolerance":0},"affichage":"9","explication":"3x − 12 = x + 6, donc 2x = 18 et x = **9**. Vérification : 3 × (9 − 4) = 15 et 9 + 6 = 15."},{"cle":{"type":"choix","ids":["b"]},"explication":"4(x + 2) = 4x + 8. L’équation devient 4x + 5 = 4x + 8, soit 5 = 8 : c’est **impossible**, donc aucune solution."}]$ex$::jsonb),
  ('efd99958-83d9-5671-9d06-d227670481cb'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le programme de calcul de Chloé","competence":"calculer","situation":"Chloé invente un programme de calcul pour épater ses amis. Elle le présente sous forme de chaîne d’opérations. Elle essaie plusieurs nombres de départ pour voir ce qui se passe.","documents":[{"id":"prog","type":"chaine","disposition":"ligne","titre":"Le programme de Chloé","noeuds":[{"id":"z1","texte":"Je choisis x"},{"id":"z2","texte":"J’ajoute 4"},{"id":"z3","texte":"Je multiplie par 2"},{"id":"z4","texte":"Je retire 8"}],"liens":[{"de":"z1","a":"z2"},{"de":"z2","a":"z3"},{"de":"z3","a":"z4"}]}],"questions":[{"enonce":"Quel est le résultat si Chloé choisit **5** ?","aide":"Suis les étapes dans l’ordre : +4, puis ×2, puis −8.","type":"nombre"},{"enonce":"Quel est le résultat si Chloé choisit **12** ?","aide":"Même démarche avec 12.","type":"nombre"},{"enonce":"Que fait ce programme ?","aide":"Compare le départ et le résultat dans tes deux essais : 5 donne 10, 12 donne 24.","type":"choix","options":[{"id":"a","texte":"Il donne toujours 8"},{"id":"b","texte":"Il triple le nombre de départ"},{"id":"c","texte":"Il double le nombre de départ"},{"id":"d","texte":"Il ajoute 4 au nombre de départ"}],"multiple":false},{"enonce":"Avec quel nombre de départ obtient-on **30** ?","aide":"Le programme double le nombre choisi : qu’est-ce que 30 est le double de ?","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10","explication":"5 + 4 = 9 ; 9 × 2 = 18 ; 18 − 8 = **10**."},{"cle":{"type":"nombre","valeur":24,"tolerance":0},"affichage":"24","explication":"12 + 4 = 16 ; 16 × 2 = 32 ; 32 − 8 = **24**."},{"cle":{"type":"choix","ids":["c"]},"explication":"L’expression est 2(x + 4) − 8 = 2x + 8 − 8 = **2x** : le programme double le nombre de départ."},{"cle":{"type":"nombre","valeur":15,"tolerance":0},"affichage":"15","explication":"Le résultat vaut 2x. 2x = 30 donne x = 30 ÷ 2 = **15**."}]$ex$::jsonb),
  ('efd99958-83d9-5671-9d06-d227670481cb'::uuid, 2, 2, 10, 35, 4,
   $ex${"titre":"Le grillage du potager rectangulaire","competence":"modeliser","situation":"Léa clôture un potager rectangulaire dont la longueur est le triple de la largeur. Elle dispose de 64 m de grillage et veut utiliser tout le grillage pour faire le tour du potager.","documents":[{"id":"plan","type":"figure","titre":"Le plan du potager","cadre":{"xmin":-1,"xmax":11,"ymin":-1,"ymax":4.5},"points":[{"id":"A","x":0,"y":0,"position":"so"},{"id":"B","x":9,"y":0,"position":"se"},{"id":"C","x":9,"y":3,"position":"ne"},{"id":"D","x":0,"y":3,"position":"no"}],"polygones":[{"sommets":["A","B","C","D"],"teinte":"vert","motif":"clair"}],"segments":[{"de":"A","a":"B","longueur":"3x"},{"de":"B","a":"C","longueur":"x"}],"textes":[{"x":4.5,"y":1.5,"texte":"Tour : 64 m"}]}],"questions":[{"enonce":"Soit x la largeur en mètres. Quelle expression donne le **périmètre** du potager ?","aide":"Le périmètre est 2 × (longueur + largeur), avec longueur = 3x.","type":"choix","options":[{"id":"a","texte":"3x²"},{"id":"b","texte":"6x"},{"id":"c","texte":"8x"},{"id":"d","texte":"4x"}],"multiple":false},{"enonce":"Résous 8x = 64 : quelle est la **largeur** du potager, en mètres ?","aide":"Divise les deux membres par 8.","type":"nombre","unite":"m"},{"enonce":"Quelle est la **longueur** du potager, en mètres ?","aide":"La longueur est le triple de la largeur.","type":"nombre","unite":"m"},{"enonce":"Quelle est l’**aire** du potager, en m² ?","aide":"Aire d’un rectangle : longueur × largeur.","type":"nombre","unite":"m²"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["c"]},"explication":"Périmètre = 2 × (3x + x) = 2 × 4x = **8x**."},{"cle":{"type":"nombre","valeur":8,"tolerance":0},"affichage":"8 m","explication":"8x = 64 donc x = 64 ÷ 8 = **8 m**."},{"cle":{"type":"nombre","valeur":24,"tolerance":0},"affichage":"24 m","explication":"Longueur = 3x = 3 × 8 = **24 m**. Vérification : 2 × (24 + 8) = 64 m de grillage."},{"cle":{"type":"nombre","valeur":192,"tolerance":0},"affichage":"192 m²","explication":"Aire = 24 × 8 = **192 m²**."}]$ex$::jsonb),
  ('efd99958-83d9-5671-9d06-d227670481cb'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Soldes en cascade","competence":"modeliser","situation":"Un magasin annonce : « −20 % sur tout, puis −10 % supplémentaires en caisse ». Aya se demande si cela fait −30 % au total. Elle regarde l’affiche et le tableau des prix.","documents":[{"id":"affiche","type":"fiche","modele":"affiche","entete":"SOLDES","sousTitre":"Tout le magasin","emoji":"🏷️","lignes":[{"texte":"−20 % sur tout"},{"texte":"puis −10 % en caisse","gras":true}],"pied":"Affiche inventée pour l’exercice","teinte":"corail"},{"id":"prix","type":"tableau","titre":"Les prix","source":"Prix inventés pour l’exercice","colonnes":["Article","Prix initial (€)","Prix à payer (€)"],"lignes":[["Blouson",80,"?"],["Casquette",20,"14,4"],["Jean",60,"43,2"],["Pull","?",36]],"enteteLignes":true}],"questions":[{"enonce":"Quel est le **prix à payer** pour le blouson ? (−20 % puis −10 % sur le prix déjà réduit)","aide":"Baisse de 20 % : multiplie par 0,8. Puis baisse de 10 % : multiplie par 0,9.","type":"nombre","unite":"€"},{"enonce":"Par quel **coefficient unique** remplace-t-on les deux baisses ?","aide":"Multiplie les deux coefficients : 0,8 × 0,9.","type":"choix","options":[{"id":"a","texte":"0,30"},{"id":"b","texte":"0,72"},{"id":"c","texte":"0,70"},{"id":"d","texte":"0,98"}],"multiple":false},{"enonce":"De quel **pourcentage** le prix baisse-t-il au total ?","aide":"Un coefficient de 0,72 signifie que le prix devient 72 % du prix de départ.","type":"nombre","unite":"%"},{"enonce":"Pourquoi la baisse totale n’est-elle pas de 30 % ?","aide":"Sur quel prix la deuxième baisse de 10 % est-elle calculée ?","type":"choix","options":[{"id":"a","texte":"Parce que 10 est plus petit que 20"},{"id":"b","texte":"Parce qu’il y a deux remises à cumuler"},{"id":"c","texte":"Parce que la loi limite les soldes à 25 %"},{"id":"d","texte":"Les 10 % portent sur le prix déjà réduit"}],"multiple":false},{"enonce":"Le pull est payé **36 €** après les deux remises. Quel était son prix initial ?","aide":"Le prix initial multiplié par 0,72 donne 36 : résous 0,72 × p = 36.","type":"nombre","unite":"€"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":57.6,"tolerance":0},"affichage":"57,6 €","explication":"80 × 0,8 = 64 ; 64 × 0,9 = **57,6 €**."},{"cle":{"type":"choix","ids":["b"]},"explication":"Les deux baisses successives se traduisent par 0,8 × 0,9 = **0,72**."},{"cle":{"type":"nombre","valeur":28,"tolerance":0},"affichage":"28 %","explication":"Le prix passe à 72 % du prix initial : la baisse est de 100 − 72 = **28 %**, et non 30 %."},{"cle":{"type":"choix","ids":["d"]},"explication":"Les 10 % sont calculés sur le prix **déjà baissé de 20 %**, donc ils représentent moins de 10 % du prix initial. On ne peut pas additionner les pourcentages."},{"cle":{"type":"nombre","valeur":50,"tolerance":0},"affichage":"50 €","explication":"0,72 × p = 36 donc p = 36 ÷ 0,72 = **50 €**. Vérification : 50 × 0,72 = 36."}]$ex$::jsonb),
  ('f6b44486-50b1-5c22-a554-1db8059cc8b7'::uuid, 1, 1, 5, 20, 4,
