  ('f6b44486-50b1-5c22-a554-1db8059cc8b7'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Les huit devoirs de Lina","competence":"calculer","situation":"Lina a eu huit devoirs de sciences au cours du trimestre. Elle veut savoir si sa moyenne reflète bien ses résultats et compare avec la médiane.","documents":[{"id":"notes","type":"tableau","titre":"Les notes de Lina (sur 20)","source":"Notes inventées pour l’exercice","colonnes":["Série","Devoir A","Devoir B","Devoir C","Devoir D"],"lignes":[["Devoirs 1 à 4",15,8,20,11],["Devoirs 5 à 8",4,17,5,16]],"enteteLignes":true}],"questions":[{"enonce":"Touche la **meilleure** et la **moins bonne** note de Lina.","aide":"Cherche le plus grand et le plus petit nombre du tableau.","type":"zone","document":"notes","multiple":true},{"enonce":"Quelle est l’**étendue** de la série de notes ?","aide":"Étendue = plus grande valeur − plus petite valeur.","type":"nombre"},{"enonce":"Quelle est la **moyenne** des huit notes ?","aide":"Additionne les 8 notes, puis divise par 8.","type":"nombre"},{"enonce":"Quelle est la **médiane** de la série ? (range d’abord les notes dans l’ordre)","aide":"Ordonnée, la série compte 8 valeurs : la médiane est entre la 4e et la 5e.","type":"nombre"},{"enonce":"Que signifie une médiane de **13** ici ?","aide":"La médiane partage la série ordonnée en deux groupes de même effectif.","type":"choix","options":[{"id":"a","texte":"La moitié des notes sont au plus 13, l’autre moitié au moins 13"},{"id":"b","texte":"Toutes les notes de Lina sont exactement égales à 13"},{"id":"c","texte":"La note qui revient le plus souvent dans la série est 13"},{"id":"d","texte":"La somme de toutes les notes de Lina est égale à 13"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c3","r1c1"]},"explication":"La meilleure note est **20** et la moins bonne **4**."},{"cle":{"type":"nombre","valeur":16,"tolerance":0},"affichage":"16","explication":"20 − 4 = **16**."},{"cle":{"type":"nombre","valeur":12,"tolerance":0},"affichage":"12","explication":"Somme : 15 + 8 + 20 + 11 + 4 + 17 + 5 + 16 = 96. Moyenne : 96 ÷ 8 = **12**."},{"cle":{"type":"nombre","valeur":13,"tolerance":0},"affichage":"13","explication":"Notes rangées : 4 ; 5 ; 8 ; 11 ; 15 ; 16 ; 17 ; 20. La médiane est la moyenne des 4e et 5e valeurs : (11 + 15) ÷ 2 = **13**."},{"cle":{"type":"choix","ids":["a"]},"explication":"Quatre notes sont inférieures ou égales à 13 (4, 5, 8, 11) et quatre sont supérieures (15, 16, 17, 20). La médiane **partage la série en deux groupes égaux**."}]$ex$::jsonb),
  ('f6b44486-50b1-5c22-a554-1db8059cc8b7'::uuid, 3, 3, 15, 50, 5,
   $ex${"titre":"Retards au collège : un relevé, deux graphiques","competence":"analyser-document","situation":"Le journal du collège titre « Les retards explosent ! » et publie un graphique. La direction publie le même relevé avec un autre graphique. Les chiffres sont les mêmes, mais l’impression est très différente.","documents":[{"id":"journal","type":"graphique","titre":"Le graphique du journal","source":"Relevé inventé pour l’exercice","forme":"barres","categories":["Sem. 1","Sem. 2","Sem. 3","Sem. 4"],"series":[{"nom":"Retards","valeurs":[82,84,85,88],"teinte":"corail"}],"axeY":{"titre":"Retards","min":80,"max":90,"pas":2},"axeX":{"titre":"Semaine"}},{"id":"direction","type":"graphique","titre":"Le graphique de la direction","source":"Mêmes données","forme":"barres","categories":["Sem. 1","Sem. 2","Sem. 3","Sem. 4"],"series":[{"nom":"Retards","valeurs":[82,84,85,88],"teinte":"corail"}],"axeY":{"titre":"Retards","min":0,"max":100,"pas":20},"axeX":{"titre":"Semaine"}}],"questions":[{"enonce":"Dans quel graphique la hausse paraît-elle **la plus spectaculaire** ?","aide":"Compare la taille de la barre de la semaine 4 avec celle de la semaine 1 dans chaque graphique.","type":"choix","options":[{"id":"a","texte":"Dans aucun des deux"},{"id":"b","texte":"Dans celui de la direction, axe de 0 à 100"},{"id":"c","texte":"Elle paraît pareille dans les deux"},{"id":"d","texte":"Dans celui du journal, axe de 80 à 90"}],"multiple":false},{"enonce":"Quelle est la **hausse réelle** des retards entre la semaine 1 et la semaine 4, en pourcentage ? (arrondi à l’unité)","aide":"Hausse = (88 − 82) ÷ 82, puis × 100.","type":"nombre","unite":"%"},{"enonce":"Quel est le **défaut** du graphique du journal ?","aide":"Lis d’abord les axes et l’échelle, avant de regarder les barres.","type":"choix","options":[{"id":"a","texte":"L’axe vertical ne part pas de zéro, ce qui exagère la hausse"},{"id":"b","texte":"Il manque le chiffre de la semaine 3 sur l’axe"},{"id":"c","texte":"Les barres sont dessinées en rouge sur fond blanc"},{"id":"d","texte":"Il y a trop de barres pour bien lire le graphique"}],"multiple":false},{"enonce":"Quelle est la **moyenne** des retards par semaine sur les 4 semaines ?","aide":"Additionne les quatre valeurs, divise par 4.","type":"nombre"},{"enonce":"Quelle est l’**étendue** de la série des retards ?","aide":"Plus grande valeur − plus petite valeur.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"choix","ids":["d"]},"explication":"Dans le graphique du journal, l’axe démarre à 80 : la barre de la semaine 4 paraît **bien plus haute** que celle de la semaine 1, alors que l’écart réel est faible."},{"cle":{"type":"nombre","valeur":7,"tolerance":0.5},"affichage":"7 %","explication":"(88 − 82) ÷ 82 = 6 ÷ 82 ≈ 0,073, soit environ **7 %** : une hausse modérée."},{"cle":{"type":"choix","ids":["a"]},"explication":"L’axe démarre à 80 : cela **déforme la perception** sans falsifier aucun chiffre. Il faut toujours lire l’axe avant de regarder les barres."},{"cle":{"type":"nombre","valeur":84.75,"tolerance":0},"affichage":"84,75","explication":"(82 + 84 + 85 + 88) ÷ 4 = 339 ÷ 4 = **84,75** retards par semaine."},{"cle":{"type":"nombre","valeur":6,"tolerance":0},"affichage":"6","explication":"88 − 82 = **6** : les retards varient peu d’une semaine à l’autre."}]$ex$::jsonb),
  ('7c7c4288-96dd-5768-b875-58bce65ca9aa'::uuid, 1, 1, 5, 20, 4,
   $ex${"titre":"Le sac de billes de Samia","competence":"calculer","situation":"Samia tire au hasard une bille dans un sac opaque. Elle a noté le contenu du sac dans un tableau.","documents":[{"id":"sac","type":"tableau","titre":"Le contenu du sac","source":"Contenu inventé pour l’exercice","colonnes":["Couleur","Rouge","Bleue","Verte"],"lignes":[["Nombre de billes",3,5,2]],"enteteLignes":true}],"questions":[{"enonce":"Combien de billes y a-t-il **en tout** dans le sac ?","aide":"Additionne les trois effectifs.","type":"nombre"},{"enonce":"Quelle est la probabilité de tirer une bille **rouge** ? (en décimal)","aide":"Probabilité = issues favorables ÷ issues possibles.","type":"nombre"},{"enonce":"Quelle couleur a la **plus grande** probabilité d’être tirée ?","aide":"La probabilité est la plus grande pour la couleur la plus fréquente.","type":"choix","options":[{"id":"a","texte":"La verte"},{"id":"b","texte":"La rouge"},{"id":"c","texte":"La bleue"},{"id":"d","texte":"Elles ont la même probabilité"}],"multiple":false},{"enonce":"Quelle est la probabilité de **ne pas** tirer une bille verte ? (en décimal)","aide":"L’événement contraire : 1 − P(verte).","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":10,"tolerance":0},"affichage":"10","explication":"3 + 5 + 2 = **10 billes**."},{"cle":{"type":"nombre","valeur":0.3,"tolerance":0},"affichage":"0,3","explication":"Il y a 3 billes rouges sur 10 : P = {{3/10}} = **0,3**."},{"cle":{"type":"choix","ids":["c"]},"explication":"Il y a 5 billes bleues, plus que de rouges (3) ou de vertes (2) : P(bleue) = {{5/10}} = 0,5, la **plus grande**."},{"cle":{"type":"nombre","valeur":0.8,"tolerance":0},"affichage":"0,8","explication":"P(verte) = {{2/10}} = 0,2, donc P(non verte) = 1 − 0,2 = **0,8**."}]$ex$::jsonb),
  ('7c7c4288-96dd-5768-b875-58bce65ca9aa'::uuid, 2, 2, 10, 35, 5,
   $ex${"titre":"Le jeu des deux dés","competence":"raisonner","situation":"Dans un jeu de plateau, on lance deux dés équilibrés à six faces et on additionne les résultats. Ce tableau donne toutes les sommes possibles : chaque case est également probable.","documents":[{"id":"sommes","type":"tableau","titre":"Toutes les sommes possibles","colonnes":["Dé 1 ↓ · Dé 2 →","1","2","3","4","5","6"],"lignes":[[1,2,3,4,5,6,7],[2,3,4,5,6,7,8],[3,4,5,6,7,8,9],[4,5,6,7,8,9,10],[5,6,7,8,9,10,11],[6,7,8,9,10,11,12]],"enteteLignes":true}],"questions":[{"enonce":"Touche toutes les cases où la somme vaut **7**.","aide":"La somme 7 apparaît sur une diagonale du tableau.","type":"zone","document":"sommes","multiple":true},{"enonce":"Quelle est la probabilité d’obtenir une somme égale à **7** ? (une fraction, ou un décimal arrondi au centième)","aide":"Il y a 36 cases au total, toutes équiprobables.","type":"nombre"},{"enonce":"Quelle est la probabilité d’obtenir une somme égale à **9** ? (une fraction, ou un décimal arrondi au centième)","aide":"Compte les cases où tu lis 9 dans le tableau.","type":"nombre"},{"enonce":"Quelle somme est la **plus probable** ?","aide":"Compte combien de fois chaque somme apparaît dans le tableau.","type":"choix","options":[{"id":"a","texte":"6"},{"id":"b","texte":"8"},{"id":"c","texte":"12"},{"id":"d","texte":"7"}],"multiple":false},{"enonce":"Quelle est la probabilité que la somme soit **différente de 7** ? (une fraction, ou un décimal arrondi au centième)","aide":"C’est l’événement contraire de « la somme vaut 7 ».","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r0c6","r1c5","r2c4","r3c3","r4c2","r5c1"]},"explication":"La somme 7 apparaît **6 fois** : 1 + 6, 2 + 5, 3 + 4, 4 + 3, 5 + 2, 6 + 1."},{"cle":{"type":"nombre","valeur":0.16666666666666666,"tolerance":0.005},"affichage":"0,1667","explication":"6 cases favorables sur 36 : P = {{6/36}} = **{{1/6}}**. En décimal : environ 0,17."},{"cle":{"type":"nombre","valeur":0.1111111111111111,"tolerance":0.005},"affichage":"0,1111","explication":"La somme 9 apparaît 4 fois (3 + 6, 4 + 5, 5 + 4, 6 + 3) : P = {{4/36}} = **{{1/9}}**."},{"cle":{"type":"choix","ids":["d"]},"explication":"La somme 7 apparaît 6 fois, plus que toute autre (6 et 8 apparaissent 5 fois chacune, 12 une seule fois). C’est la **plus probable**."},{"cle":{"type":"nombre","valeur":0.8333333333333334,"tolerance":0.005},"affichage":"0,8333","explication":"P(non 7) = 1 − {{1/6}} = **{{5/6}}**."}]$ex$::jsonb),
